window.SSAI_YOTEN_CARDS={"論理国語||文章の構成と接続語":{"points":[{"word":"序論・本論・結論","text":"文章全体の基本構成。序論で問題や話題を提示し、本論で根拠や具体例を示して考えを展開し、結論で主張をまとめる。","diagram":{"type":"flow","title":"文章の三部構成","items":[{"label":"序論","sub":"問題や話題を提示する"},{"label":"本論","sub":"根拠や具体例で考えを展開する"},{"label":"結論","sub":"主張をまとめる"}]}},{"word":"順接","text":"前の内容を受けて、自然な流れで後の内容につなぐ関係。「だから」「そこで」などが使われる。"},{"word":"逆接","text":"前の内容から予想される流れに反する内容につなぐ関係。「しかし」「だが」などが使われる。筆者の主張が現れやすい場所でもある。"},{"word":"添加・並列","text":"前の内容に別の内容を付け加えたり、並べたりする関係。「また」「さらに」「および」などが使われる。"},{"word":"対比の接続語","text":"二つの事柄を比べる関係を示す。「一方」「これに対して」などが使われ、違いを際立たせる。"},{"word":"換言の接続語","text":"前の内容を別の言葉で言い換える関係。「つまり」「すなわち」などが使われ、その後に要旨が述べられることが多い。"}]},"論理国語||段落の役割と要旨":{"points":[{"word":"段落","text":"一つの内容のまとまりを表す文章の単位。改行して書き始め、ふつう一つの段落には中心となる内容が一つ入る。"},{"word":"中心文","text":"段落の内容をまとめた文。その段落で最も伝えたいことが書かれており、段落の最初や最後に置かれることが多い。"},{"word":"要旨","text":"文章全体の要点を短くまとめたもの。筆者の主張とその根拠の中心部分を取り出すことで作る。","diagram":{"type":"flow","title":"要旨の作り方","items":[{"label":"筆者の主張","sub":"最も伝えたいこと"},{"label":"その根拠","sub":"主張を支える中心部分"},{"label":"要旨","sub":"主張と根拠を短くまとめたもの"}]}},{"word":"具体例の段落","text":"抽象的な主張を分かりやすくするために、実際の例を示す段落。「たとえば」で始まることが多い。"},{"word":"話題の転換","text":"段落の変わり目で、話題が新しい方向へ移ること。「ところで」「次に」などの言葉が目印になる。"},{"word":"段落構成図","text":"各段落の役割と段落どうしの関係を図に整理したもの。文章の論理の流れを一目で確かめるのに役立つ。"}]},"論理国語||論理の展開と根拠":{"points":[{"word":"主張","text":"筆者が最も伝えたい考えや意見。文章の結論部分に置かれることが多い。"},{"word":"根拠","text":"主張を支える理由や証拠。事実、データ、具体例などが使われ、主張との関連が強いほど説得力が増す。"},{"word":"帰納法","text":"いくつかの具体的な事例から、共通する一般的な結論を導く考え方。","diagram":{"type":"flow","title":"帰納法の進み方","items":[{"label":"具体的な事例","sub":"いくつかの事実を集める"},{"label":"共通点を探す","sub":"事例に共通する傾向"},{"label":"一般的な結論","sub":"広く当てはまる結論を導く"}]}},{"word":"演繹法","text":"一般的な原則や前提から、個別の結論を導く考え方。前提が正しければ結論も正しくなる。","diagram":{"type":"flow","title":"演繹法の進み方","items":[{"label":"一般的な原則・前提","sub":"出発点となる決まりや事実"},{"label":"個別の事柄に当てる","sub":"前提を具体的な場合へ"},{"label":"個別の結論","sub":"前提が正しければ結論も正しい"}]}},{"word":"論理の飛躍","text":"根拠から結論へ進む途中で、必要な説明や証拠が不足していること。説得力を弱める原因になる。"},{"word":"事実と意見","text":"事実は確かめられる事柄、意見は人の考えや判断。文章を読むときは両者を区別することが大切。"}]},"論理国語||対比と例示":{"points":[{"word":"対比","text":"性質の異なる二つの事柄を並べて比べ、違いを際立たせる表現方法。「一方」「に対して」が目印になる。"},{"word":"二項対立","text":"物事を二つの対立する側面に分けて考える枠組み。単純化しすぎると大事な点を見落とすこともある。"},{"word":"例示","text":"抽象的な説明に具体例を添えて、理解しやすくすること。「たとえば」「具体的には」が目印になる。"},{"word":"対照実験的な説明","text":"条件の違う二つの場合を比べて示す説明の仕方。違いの原因を考えさせる働きがある。"},{"word":"類比","text":"似た別の事柄になぞらえて説明する方法。たとえ話がこれにあたる。"},{"word":"具体と抽象の往復","text":"具体例でイメージを作り、抽象的な原則にまとめ直す読み方・書き方の基本的な動き。","diagram":{"type":"flow","title":"具体と抽象の往復","items":[{"label":"具体例","sub":"実際の例でイメージを作る"},{"label":"抽象的な原則","sub":"共通する決まりにまとめ直す"},{"label":"別の具体例で確かめる","sub":"原則が当てはまるか確かめる"}]}}]},"論理国語||抽象と具体":{"points":[{"word":"抽象","text":"個々のものから共通する性質を取り出して、一般的に表すこと。「動物」「道具」などが抽象度の高い言葉。"},{"word":"具体","text":"実際に目に見えたり思い浮かべたりできる、個別のものを表すこと。「飼っている犬のポチ」などが具体的。"},{"word":"上位概念と下位概念","text":"「くだもの」は上位概念、「りんご」「みかん」は下位概念。抽象度の高低で言葉を整理する考え方。","diagram":{"type":"causal","title":"上位概念と下位概念","items":[{"label":"くだもの（上位概念）","sub":"抽象度が高い言葉"},{"label":"りんご・みかん（下位概念）","sub":"抽象度が低い、より具体的な言葉"}]}},{"word":"一般化","text":"個別の事例から共通の傾向を取り出して、広く当てはまる言い方にすること。行き過ぎると誤りになりやすい。"},{"word":"抽象化の落とし穴","text":"抽象的な言葉だけで話が進み、実際の内容が伴わないこと。具体例で確かめることが大切。"},{"word":"定義","text":"言葉の意味をはっきり定めること。論理的な文章では、重要な言葉の定義から議論が始まることが多い。"}]},"日本史||江戸幕府の成立":{"points":[{"word":"徳川家康","text":"関ヶ原の戦いに勝利し、1603年に征夷大将軍となって江戸幕府を開いた人物。"},{"word":"関ヶ原の戦い","text":"1600年、徳川家康の東軍と石田三成らの西軍が戦った天下分け目の戦い。家康が勝利した。","diagram":{"type":"timeline","title":"幕府成立までの流れ","items":[{"label":"1600年 関ヶ原の戦い","sub":"家康の東軍が勝利"},{"label":"1603年 江戸幕府を開く","sub":"家康が征夷大将軍になる"},{"label":"1614〜15年 大坂の陣","sub":"豊臣家が滅亡する"}]}},{"word":"大坂の陣","text":"1614〜15年、幕府が大坂城の豊臣秀頼を攻めた戦い。これにより豊臣家は滅亡した。"},{"word":"武家諸法度","text":"幕府が大名の守るべき決まりを定めた法令。城の修理や婚姻にも幕府の許可が必要とされた。"},{"word":"参勤交代","text":"大名が1年おきに江戸と領地を行き来する制度。3代将軍家光のときに武家諸法度で義務づけられた。妻子は江戸に住んだ。","diagram":{"type":"flow","title":"参勤交代のしくみ","items":[{"label":"大名が江戸へ参勤","sub":"妻子は江戸に住んだまま"},{"label":"1年ほど江戸に滞在","sub":"将軍に仕える"},{"label":"領地へ帰る","sub":"翌年また江戸へ。これを繰り返す"}]}},{"word":"鎖国","text":"幕府が対外関係を制限した政策を指す言葉。貿易は長崎などでオランダ・中国などに限られ、完成は1639年ごろとされる。"}]},"日本史||明治維新":{"points":[{"word":"ペリー来航","text":"1853年、アメリカのペリーが浦賀に来航し、日本に開国を求めた出来事。","diagram":{"type":"timeline","title":"開国から幕府の終わり","items":[{"label":"1853年 ペリー来航","sub":"アメリカが開国を求める"},{"label":"1854年 日米和親条約","sub":"下田と函館を開港し開国"},{"label":"1867年 大政奉還","sub":"政権が朝廷に返され幕府が終わる"}]}},{"word":"日米和親条約","text":"1854年に結ばれた条約。下田と函館を開港し、日本は開国した。"},{"word":"大政奉還","text":"1867年、将軍徳川慶喜が政権を朝廷に返したこと。これにより江戸幕府は終わった。"},{"word":"廃藩置県","text":"1871年、藩を廃止して県を置き、知事を政府が任命した改革。中央集権化が進んだ。"},{"word":"地租改正","text":"1873年から行われた税制改革。土地の価格（地価）の3%を現金で納める形にし、政府の財政を安定させた。"},{"word":"殖産興業","text":"政府が産業を育てて国を豊かにしようとした政策。官営工場の設立などが進められた。"}]},"日本史||縄文・弥生時代":{"points":[{"word":"縄文土器","text":"縄文時代に使われた、表面に縄目の文様がある厚手の土器。煮炊きに使われた。"},{"word":"貝塚","text":"縄文時代の人々が食べた貝殻などを捨てた跡。当時の食生活や環境を知る手がかりになる。"},{"word":"三内丸山遺跡","text":"青森県にある縄文時代の大規模な集落跡。大型の建物跡などが見つかっている。"},{"word":"弥生土器","text":"弥生時代に使われた、薄手で赤褐色の土器。縄文土器より高温で焼かれた。"},{"word":"稲作の伝来","text":"弥生時代の初めごろ、大陸や朝鮮半島から水田稲作が伝わり、食料の生産が始まった。","diagram":{"type":"causal","title":"稲作の伝来","items":[{"label":"大陸・朝鮮半島から水田稲作が伝わる","sub":"弥生時代の初めごろ"},{"label":"食料の生産が始まる","sub":"狩りや採取だけに頼らない生活へ"}]}},{"word":"吉野ヶ里遺跡","text":"佐賀県にある弥生時代の大規模な環濠集落の跡。物見やぐらや墳丘墓が見つかっている。"},{"word":"邪馬台国","text":"3世紀ごろ日本にあったとされる国。中国の史書「魏志倭人伝」に記され、女王卑弥呼が治めた。"}]},"日本史||鎌倉幕府と武士の社会":{"points":[{"word":"源頼朝","text":"1192年に征夷大将軍に任命され、鎌倉幕府を開いたとされる武士の棟梁。"},{"word":"守護・地頭","text":"幕府が各地に置いた役職。守護は国ごとの治安維持、地頭は荘園や公領の管理を担当した。"},{"word":"御恩と奉公","text":"将軍が御家人の土地支配を認める「御恩」と、御家人が軍事的に仕える「奉公」からなる主従関係。","diagram":{"type":"causal","title":"御恩と奉公の関係","items":[{"label":"将軍の御恩","sub":"御家人の土地支配を認める"},{"label":"御家人の奉公","sub":"戦いのときに軍事的に仕える"}]}},{"word":"執権政治","text":"将軍を補佐する執権が実権を握った政治。北条氏が代々執権を務めた。"},{"word":"元寇","text":"1274年と1281年、元のフビライが日本へ攻めてきた出来事。暴風雨などもあって元軍は退いた。","diagram":{"type":"timeline","title":"元寇（蒙古襲来）","items":[{"label":"1274年 元軍が攻めてくる","sub":"文永の役"},{"label":"1281年 再び攻めてくる","sub":"弘安の役"},{"label":"暴風雨などで元軍が退く","sub":"日本は征服を免れた"}]}},{"word":"御成敗式目","text":"1232年に北条泰時が定めた武家社会の法令。裁判の基準を示した。"}]},"日本史||戦国時代と織田・豊臣":{"points":[{"word":"応仁の乱","text":"1467年に始まった内乱。将軍の後継争いなどが原因で、幕府の力が弱まり戦国時代のきっかけとなった。"},{"word":"下剋上","text":"身分の低い者が実力で上の者を倒して地位を奪うこと。戦国時代を象徴する言葉。"},{"word":"織田信長","text":"尾張の戦国大名。桶狭間の戦いで今川義元を破り、楽市・楽座などの政策で統一事業を進めた。"},{"word":"楽市・楽座","text":"市場の税を免除し、座（同業者組合）の特権を廃止して、商業を活発にしようとした信長の政策。"},{"word":"豊臣秀吉","text":"信長の後を継いで全国統一を果たした人物。太閤検地や刀狩を行った。"},{"word":"太閤検地","text":"秀吉が全国で行った土地調査。田畑の面積と収穫量を統一した基準で測り、年貢の基準を定めた。","diagram":{"type":"flow","title":"太閤検地の進め方","items":[{"label":"全国の田畑を測る","sub":"面積を統一した基準で調査"},{"label":"収穫量を決める","sub":"土地ごとに石高を定める"},{"label":"年貢の基準になる","sub":"秀吉の支配の土台"}]}},{"word":"刀狩","text":"1588年、農民から武器を取り上げた政策。兵農分離を進めるねらいがあった。"}]},"日本史||太平洋戦争と戦後":{"points":[{"word":"太平洋戦争","text":"1941年、日本軍の真珠湾攻撃で始まったアメリカなどとの戦争。1945年に日本の敗戦で終わった。","diagram":{"type":"timeline","title":"太平洋戦争の流れ","items":[{"label":"1941年 真珠湾攻撃","sub":"アメリカなどとの戦争が始まる"},{"label":"1945年 ポツダム宣言を受け入れる","sub":"日本が降伏を決める"},{"label":"1945年 敗戦","sub":"戦争が終わる"}]}},{"word":"ポツダム宣言","text":"1945年に連合国が出した、日本に降伏を求める宣言。日本はこれを受け入れて降伏した。"},{"word":"日本国憲法","text":"1946年に公布され、1947年に施行された憲法。国民主権・平和主義・基本的人権の尊重が三つの原則。","diagram":{"type":"timeline","title":"日本国憲法の成立","items":[{"label":"1946年 公布","sub":"新しい憲法が示される"},{"label":"1947年 施行","sub":"国民主権・平和主義・基本的人権の尊重が原則に"}]}},{"word":"農地改革","text":"戦後の改革の一つ。地主の土地を政府が買い上げて小作人に安く売り、自作農を増やした。"},{"word":"サンフランシスコ平和条約","text":"1951年に結ばれた講和条約。これにより日本は独立を回復した（沖縄などはアメリカの統治下に残った）。"},{"word":"高度経済成長","text":"1950年代半ばから1970年代初めまで、日本の経済が年平均10%前後で大きく成長した時期。"}]},"世界史||フランス革命":{"points":[{"word":"旧体制（アンシャン・レジーム）","text":"革命前のフランスの身分制社会。聖職者（第一身分）と貴族（第二身分）が特権を持ち、平民（第三身分）が税を負担した。","diagram":{"type":"causal","title":"旧体制の身分と負担","items":[{"label":"第一身分：聖職者","sub":"特権を持っていた"},{"label":"第二身分：貴族","sub":"特権を持っていた"},{"label":"第三身分：平民","sub":"税の負担を担った"}]}},{"word":"三部会","text":"聖職者・貴族・平民の三身分からなる議会。1789年、財政危機のためにルイ16世が招集したことが革命のきっかけとなった。","diagram":{"type":"timeline","title":"1789年 革命の始まり","items":[{"label":"三部会の招集","sub":"財政危機のためルイ16世が招集"},{"label":"バスティーユ襲撃（7月14日）","sub":"パリの民衆が牢獄を襲う"},{"label":"人権宣言","sub":"自由・平等・国民主権をうたう"}]}},{"word":"バスティーユ襲撃","text":"1789年7月14日、パリの民衆がバスティーユ牢獄を襲撃した出来事。フランス革命の始まりとされる。"},{"word":"人権宣言","text":"1789年に出された「人間と市民の権利の宣言」。自由・平等・国民主権などをうたい、近代民主主義の基礎となった。"},{"word":"ロベスピエール","text":"革命の指導者の一人。恐怖政治を主導したが、1794年に失脚して処刑された。"},{"word":"ナポレオン","text":"1799年にクーデタで権力を握り、後に皇帝となった軍人。ナポレオン法典を制定し、革命の成果を各地に広げた。"}]},"世界史||古代ギリシャとローマ":{"points":[{"word":"ポリス","text":"古代ギリシャの都市国家。アテネやスパルタが代表的で、それぞれ独立して政治を行った。"},{"word":"アテネの民主政","text":"成人男性市民が民会で政治に参加した制度。ただし女性や奴隷は参加できなかった。"},{"word":"ペルシア戦争","text":"紀元前5世紀、ペルシア帝国の侵攻をギリシャのポリス連合が退けた戦争。"},{"word":"アレクサンドロス大王","text":"マケドニアの王。東方へ遠征して大帝国を築き、ヘレニズム文化が生まれるきっかけを作った。","diagram":{"type":"causal","title":"ヘレニズム文化の成立","items":[{"label":"アレクサンドロス大王の東方遠征","sub":"マケドニアの王が大帝国を築く"},{"label":"ギリシャ文化と東方の文化が出会う","sub":"帝国内で文化が混ざり合う"},{"label":"ヘレニズム文化が生まれる","sub":"新しい文化の広がり"}]}},{"word":"ローマ帝国","text":"紀元前27年、オクタウィアヌスがアウグストゥスの称号を得て始まった帝政ローマ。地中海世界を支配した。"},{"word":"パクス・ロマーナ","text":"「ローマの平和」という意味。帝政初期の約200年間、帝国内が比較的平和で安定した時期を指す。"}]},"世界史||産業革命":{"points":[{"word":"蒸気機関","text":"ワットが改良した動力機関。工場の機械や蒸気機関車・蒸気船に使われ、産業革命の原動力となった。"},{"word":"工場制機械工業","text":"工場に労働者を集め、機械を使って大量生産を行うしくみ。それまでの手工業に取って代わった。","diagram":{"type":"flow","title":"工場制機械工業のしくみ","items":[{"label":"工場に労働者を集める","sub":"働く場所が家庭から工場へ"},{"label":"機械を使って生産する","sub":"蒸気機関などの動力を利用"},{"label":"大量生産が可能になる","sub":"手工業に取って代わる"}]}},{"word":"綿工業","text":"産業革命が最初に進んだ産業分野。インド産綿布に対抗して、イギリスで機械化が進んだ。"},{"word":"資本主義","text":"生産手段を持つ資本家が労働者を雇い、利潤を追求する経済のしくみ。産業革命を背景に発達した。"},{"word":"労働問題","text":"長時間労働や低賃金、児童労働など、産業革命の進展とともに深刻化した問題。労働運動や社会主義思想の背景となった。"},{"word":"都市化","text":"工場のある都市へ人口が集中すること。衛生環境の悪化などの都市問題も生まれた。","diagram":{"type":"causal","title":"都市化と都市問題","items":[{"label":"工場のある都市へ人口が集中","sub":"働き口を求めて人々が移る"},{"label":"都市問題が生まれる","sub":"衛生環境の悪化など"}]}}]},"世界史||中国の王朝":{"points":[{"word":"始皇帝","text":"紀元前221年に中国を統一した秦の王。皇帝の称号を初めて使い、文字や貨幣などを統一した。"},{"word":"漢","text":"劉邦が建てた王朝。武帝の時代に儒教が重んじられ、シルクロードを通じた交易も行われた。"},{"word":"唐","text":"7世紀に中国を統一した王朝。都の長安は国際都市として栄え、律令制や文化が日本にも影響を与えた。"},{"word":"科挙","text":"試験によって官僚を選ぶ制度。隋で始まり、唐・宋以降に整えられ、家柄より学力を重んじるしくみとなった。","diagram":{"type":"flow","title":"科挙のしくみ","items":[{"label":"試験を受ける","sub":"学力を試される"},{"label":"合格する","sub":"家柄より学力が重んじられる"},{"label":"官僚に選ばれる","sub":"国を治める役人になる"}]}},{"word":"元","text":"モンゴル人のフビライが建てた王朝。中国全土を支配し、日本へも遠征した（元寇）。"},{"word":"清","text":"満州族が建てた中国最後の王朝。19世紀にはアヘン戦争でイギリスに敗れ、半植民地化が進んだ。"}]},"世界史||ルネサンスと大航海時代":{"points":[{"word":"ルネサンス","text":"古代ギリシャ・ローマの文化を復興しようとする動き。「文芸復興」とも訳され、イタリアから広がった。"},{"word":"レオナルド・ダ・ヴィンチ","text":"「モナ・リザ」などで知られるルネサンス期の芸術家。科学や解剖学にも関心を持った万能の天才とされる。"},{"word":"宗教改革","text":"16世紀、ルターらがカトリック教会を批判して始めた改革運動。プロテスタントと呼ばれる新しい教会が生まれた。"},{"word":"コロンブス","text":"1492年、大西洋を横断してアメリカ大陸に到達した航海者。スペインの支援を受けた。","diagram":{"type":"timeline","title":"大航海時代の航海","items":[{"label":"1492年 コロンブス","sub":"大西洋を横断しアメリカ大陸に到達"},{"label":"1498年 バスコ・ダ・ガマ","sub":"アフリカ南端を回ってインドに到達"},{"label":"1522年 マゼランの船隊","sub":"世界一周を成し遂げる"}]}},{"word":"マゼラン","text":"世界一周航海を始めた航海者。途中で亡くなったが、船隊は1522年に世界一周を成し遂げた。"},{"word":"バスコ・ダ・ガマ","text":"1498年、アフリカ南端を回ってインドに到達したポルトガルの航海者。香辛料貿易の航路が開かれた。"}]},"世界史||第一次世界大戦":{"points":[{"word":"三国同盟と三国協商","text":"ドイツ・オーストリア・イタリアの同盟と、イギリス・フランス・ロシアの協商。大戦前のヨーロッパの対立構造。","diagram":{"type":"causal","title":"大戦前の対立構造","items":[{"label":"三国同盟","sub":"ドイツ・オーストリア・イタリア"},{"label":"三国協商","sub":"イギリス・フランス・ロシア"}]}},{"word":"サラエボ事件","text":"1914年、オーストリアの皇位継承者が暗殺された事件。第一次世界大戦のきっかけとなった。","diagram":{"type":"timeline","title":"大戦から講和へ","items":[{"label":"1914年 サラエボ事件","sub":"大戦のきっかけになる"},{"label":"1919年 ヴェルサイユ条約","sub":"ドイツに厳しい条件を課す"},{"label":"1920年 国際連盟の設立","sub":"国際平和の機構が生まれる"}]}},{"word":"総力戦","text":"国民や経済の全てを戦争に動員する戦争の形。第一次世界大戦で本格化した。"},{"word":"ヴェルサイユ条約","text":"1919年に結ばれた第一次世界大戦の講和条約。ドイツに厳しい賠償や軍備制限を課した。"},{"word":"国際連盟","text":"1920年に設立された国際平和機構。本部はジュネーブ。アメリカが参加しなかったことなどが弱点となった。"},{"word":"ロシア革命","text":"1917年、大戦中にロシアで起きた革命。レーニンの指導で世界初の社会主義政権が生まれた。"}]},"倫理||ギリシャの哲学者たち":{"points":[{"word":"ソクラテス","text":"対話（問答法）によって相手に無知を自覚させ、真理を探ろうとした哲学者。「無知の知」で知られる。"},{"word":"無知の知","text":"自分が何も知らないことを自覚することが、知恵の始まりであるというソクラテスの考え。"},{"word":"プラトン","text":"ソクラテスの弟子。本当の実在は「イデア」であるとするイデア論を唱え、著書「国家」で理想の国制を論じた。","diagram":{"type":"causal","title":"哲学者たちの師弟の流れ","items":[{"label":"ソクラテス","sub":"問答法で無知の知を説く"},{"label":"プラトン","sub":"ソクラテスの弟子。イデア論を唱える"},{"label":"アリストテレス","sub":"プラトンの弟子。万学の祖と呼ばれる"}]}},{"word":"イデア","text":"感覚で捉えられるものの背後にある、完全な本質・真実在というプラトンの考え。"},{"word":"アリストテレス","text":"プラトンの弟子。論理学や自然学など多くの学問を体系化し、「万学の祖」と呼ばれる。"},{"word":"ソフィスト","text":"弁論術を教えた職業教師たち。「人間は万物の尺度」と唱えたプロタゴラスが代表的。相対主義的な考えを持った。"}]},"倫理||仏教の思想":{"points":[{"word":"ゴータマ（釈迦）","text":"仏教の開祖。苦行の末に悟りを開き、人々に教えを説いた。ブッダ（目覚めた人）とも呼ばれる。"},{"word":"四苦八苦","text":"生・老・病・死の四苦など、人生につきまとう苦しみの総称。仏教の出発点となる見方。","diagram":{"type":"flow","title":"苦しみから解脱へ","items":[{"label":"四苦八苦","sub":"生・老・病・死など人生の苦しみ"},{"label":"煩悩が苦しみを生む","sub":"欲望や怒りが心を惑わせる"},{"label":"解脱","sub":"苦しみの束縛から解き放たれる"}]}},{"word":"煩悩","text":"欲望や怒りなど、心を惑わせて苦しみを生むはたらき。悟りの妨げとされる。"},{"word":"解脱","text":"煩悩による苦しみの束縛から解き放たれ、悟りの境地に至ること。"},{"word":"大乗仏教","text":"自分だけでなく多くの人々の救済を目指す仏教の流れ。菩薩の実践を重んじ、日本に伝わった仏教の中心となった。"},{"word":"縁起","text":"すべてのものは原因と条件によって生じ、互いに依存し合っているという仏教の根本的な考え。"}]},"倫理||キリスト教とイスラム教":{"points":[{"word":"イエス","text":"キリスト教の中心人物。神の愛と隣人愛を説き、十字架にかけられたと伝えられる。"},{"word":"隣人愛","text":"自分のように隣人を愛すること。イエスが説いたキリスト教の中心的な教え（アガペー）。"},{"word":"聖書","text":"キリスト教の聖典。旧約聖書と新約聖書からなる。新約聖書にはイエスの生涯や教えが記されている。"},{"word":"ムハンマド","text":"イスラム教の開祖で、神（アッラー）の預言者とされる。7世紀にアラビア半島で教えを広めた。"},{"word":"コーラン","text":"イスラム教の聖典。ムハンマドが神から受けたとされる啓示をまとめたもの。"},{"word":"五行","text":"イスラム教徒の義務とされる五つの実践。信仰告白・礼拝・喜捨・断食・巡礼を指す。","diagram":{"type":"causal","title":"イスラム教の五行","items":[{"label":"信仰告白","sub":"唯一神アッラーへの信仰を告白する"},{"label":"礼拝","sub":"神に祈る"},{"label":"喜捨","sub":"困っている人に施しをする"},{"label":"断食","sub":"一定期間、飲食を断つ"},{"label":"巡礼","sub":"聖地メッカを訪れる"}]}}]},"倫理||日本の思想":{"points":[{"word":"神道","text":"日本古来の信仰。自然や祖先を神として敬い、八百万の神という考え方を持つ。"},{"word":"浄土信仰","text":"阿弥陀仏を信じて極楽浄土への往生を願う信仰。平安時代末から鎌倉時代にかけて広がった。"},{"word":"法然と親鸞","text":"法然は浄土宗、弟子の親鸞は浄土真宗を開いた鎌倉時代の僧。念仏による救済を説いた。","diagram":{"type":"causal","title":"法然と親鸞","items":[{"label":"法然","sub":"浄土宗を開く。念仏による救済を説く"},{"label":"親鸞","sub":"法然の弟子。浄土真宗を開く"}]}},{"word":"朱子学","text":"中国で朱熹が大成した儒学の一派。江戸幕府に重んじられ、身分秩序を支える思想となった。"},{"word":"本居宣長","text":"江戸時代の国学者。「古事記伝」を著し、日本古来の精神（大和心）を明らかにしようとした。"},{"word":"福沢諭吉","text":"明治時代の思想家・教育者。「学問のすゝめ」で人々の自立と学問の大切さを説いた。"}]},"倫理||近代の哲学者":{"points":[{"word":"デカルト","text":"「我思う、ゆえに我あり」で知られる哲学者。すべてを疑う方法（方法的懐疑）から確実な知識を求めた。"},{"word":"合理論","text":"知識の源は理性にあるとする立場。デカルトが代表的。経験を重んじる経験論と対比される。"},{"word":"経験論","text":"知識は感覚の経験から得られるとする立場。ロックやヒュームが代表的。"},{"word":"カント","text":"合理論と経験論を統合しようとした哲学者。著書「純粋理性批判」で人間の認識の仕組みを検討した。","diagram":{"type":"causal","title":"合理論と経験論、そしてカント","items":[{"label":"合理論","sub":"知識の源は理性にある（デカルト）"},{"label":"経験論","sub":"知識は感覚の経験から得られる（ロックら）"},{"label":"カント","sub":"両者を統合しようとした"}]}},{"word":"ベンサム","text":"功利主義を唱えた思想家。「最大多数の最大幸福」を社会の善の基準とした。"},{"word":"ニーチェ","text":"伝統的な道徳や宗教の価値を批判し、「神は死んだ」という言葉で知られる哲学者。"}]},"政治・経済||日本国憲法の基本原則":{"points":[{"word":"国民主権","text":"国の政治のあり方を最終的に決める力（主権）は国民にあるという原則。憲法の前文と第1条に表れている。","diagram":{"type":"causal","title":"日本国憲法の三つの原則","items":[{"label":"国民主権","sub":"主権は国民にある"},{"label":"平和主義","sub":"第9条で戦争の放棄を定める"},{"label":"基本的人権の尊重","sub":"生まれながらの権利を大切にする"}]}},{"word":"平和主義","text":"戦争を放棄し、平和を守ろうとする原則。憲法第9条で戦争の放棄と戦力の不保持が定められている。"},{"word":"基本的人権の尊重","text":"人間が生まれながらに持つ権利を大切にする原則。第11条で「侵すことのできない永久の権利」とされる。"},{"word":"象徴天皇制","text":"天皇は日本国と国民統合の象徴であり、国政に関する権能を持たないとするしくみ。第1条に定められている。"},{"word":"立憲主義","text":"憲法によって国家権力を制限し、国民の権利を守るという考え方。憲法が国の最高法規であることと結びつく。"},{"word":"最高法規","text":"憲法は国の法の中で最も強い効力を持ち、憲法に反する法律や命令は効力を持たない（第98条）。"}]},"政治・経済||国会・内閣・裁判所":{"points":[{"word":"三権分立","text":"立法・行政・司法の三つの権力を別々の機関に分け、互いに抑制と均衡を図るしくみ。権力の集中を防ぐ。","diagram":{"type":"causal","title":"三権分立","items":[{"label":"立法：国会","sub":"法律を作る"},{"label":"行政：内閣","sub":"政治を実行する"},{"label":"司法：裁判所","sub":"争いを裁く。互いに抑制と均衡を図る"}]}},{"word":"国会","text":"衆議院と参議院からなる立法機関。「国権の最高機関」「国の唯一の立法機関」と憲法に定められている。"},{"word":"衆議院の優越","text":"予算や条約、内閣総理大臣の指名などで、衆議院の議決が参議院より優先されるしくみ。任期が短く解散があるため民意を反映しやすいと考えられている。"},{"word":"内閣","text":"行政権を担う機関。内閣総理大臣と国務大臣からなり、国会に対して連帯して責任を負う（議院内閣制）。"},{"word":"裁判所","text":"司法権を担う機関。最高裁判所と下級裁判所があり、法律が憲法に違反しないかを判断する違憲審査権を持つ。"},{"word":"議院内閣制","text":"内閣が国会の信任に基づいて成立し、国会に責任を負う制度。不信任決議が可決されれば内閣は総辞職か衆議院解散を選ぶ。","diagram":{"type":"flow","title":"議院内閣制のしくみ","items":[{"label":"国会の信任に基づいて内閣が成立","sub":"内閣は国会に責任を負う"},{"label":"不信任決議が可決されたら","sub":"内閣は対応を選ぶ"},{"label":"総辞職か衆議院の解散","sub":"どちらかを行う"}]}}]},"政治・経済||選挙と政党":{"points":[{"word":"選挙の四原則","text":"普通選挙（一定年齢以上の全員に選挙権）、平等選挙（一人一票）、直接選挙（代表を直接選ぶ）、秘密選挙（投票の秘密を守る）。","diagram":{"type":"causal","title":"選挙の四原則","items":[{"label":"普通選挙","sub":"一定年齢以上の全員に選挙権"},{"label":"平等選挙","sub":"一人一票"},{"label":"直接選挙","sub":"代表を直接選ぶ"},{"label":"秘密選挙","sub":"投票の秘密を守る"}]}},{"word":"小選挙区制","text":"一つの選挙区から一人だけを選ぶ制度。大政党に有利で政権交代が起こりやすい一方、死票が多くなる。"},{"word":"比例代表制","text":"政党の得票率に応じて議席を配分する制度。少数意見が反映されやすいが、小政党が乱立しやすい。"},{"word":"小選挙区比例代表並立制","text":"衆議院議員選挙で採用されている、小選挙区制と比例代表制を組み合わせた制度。","diagram":{"type":"causal","title":"小選挙区比例代表並立制","items":[{"label":"小選挙区制","sub":"選挙区ごとに一人を選ぶ"},{"label":"比例代表制","sub":"政党の得票率で議席を配分する"},{"label":"二つを組み合わせる","sub":"衆議院議員選挙で採用"}]}},{"word":"与党と野党","text":"与党は政権を担う政党、野党は政権に就いていない政党。与党と内閣を監視し、対案を示す役割を持つ。"},{"word":"一票の格差","text":"選挙区によって一票の価値に差が生じる問題。裁判で違憲状態と判断されたことがある。"}]},"政治・経済||需要と供給":{"points":[{"word":"需要","text":"ある価格で、消費者が買おうとする商品の量。ふつう価格が下がるほど需要量は増える。"},{"word":"供給","text":"ある価格で、生産者が売ろうとする商品の量。ふつう価格が上がるほど供給量は増える。"},{"word":"均衡価格","text":"需要量と供給量が一致するところで決まる価格。市場で実際に成立する価格の目安になる。","diagram":{"type":"causal","title":"均衡価格の決まり方","items":[{"label":"需要量","sub":"消費者が買おうとする量"},{"label":"供給量","sub":"生産者が売ろうとする量"},{"label":"二つが一致する価格","sub":"これが均衡価格になる"}]}},{"word":"需要曲線","text":"価格と需要量の関係を表す右下がりの曲線（グラフ）。価格が下がると需要量が増える関係を示す。"},{"word":"供給曲線","text":"価格と供給量の関係を表す右上がりの曲線（グラフ）。価格が上がると供給量が増える関係を示す。"},{"word":"価格の自動調節機能","text":"需要と供給の不一致を、価格の変動によって自然に調整する市場の働き。「見えざる手」とも呼ばれる。"}]},"政治・経済||金融のしくみ":{"points":[{"word":"直接金融と間接金融","text":"直接金融は株式や債券で企業が直接資金を集める方法。間接金融は銀行などが間に入って貸し出す方法。","diagram":{"type":"causal","title":"直接金融と間接金融","items":[{"label":"直接金融","sub":"株式や債券で企業が直接資金を集める"},{"label":"間接金融","sub":"銀行などが間に入って貸し出す"}]}},{"word":"日本銀行","text":"日本の中央銀行。銀行券（紙幣）の発行、物価の安定、金融システムの安定が役割。「発券銀行」「銀行の銀行」「政府の銀行」と呼ばれる。"},{"word":"金融政策","text":"中央銀行が景気や物価を安定させるために行う政策。政策金利の上げ下げが代表的。"},{"word":"政策金利","text":"中央銀行が金融機関への貸し出しなどに用いる基準金利。景気が過熱すれば上げ、不況なら下げる。","diagram":{"type":"causal","title":"政策金利の上げ下げ","items":[{"label":"景気が過熱したら","sub":"政策金利を上げる"},{"label":"不況のときは","sub":"政策金利を下げる"}]}},{"word":"株式","text":"株式会社が事業資金を集めるために発行する証券。買った人は株主となり、配当や株主総会での議決権を持つ。"},{"word":"預金保険制度","text":"銀行が破綻しても、預金者一人につき元本1000万円とその利息までを保護する制度。"}]},"情報||ネットワークとセキュリティ":{"points":[{"word":"プロトコル","text":"ネットワークでデータをやり取りするための約束事・手順の決まり。TCP/IPが代表的。"},{"word":"IPアドレス","text":"ネットワーク上の機器を識別するための番号。インターネット上の住所のような役割を持つ。"},{"word":"パケット","text":"データを小さく分割した単位。パケット通信では、分割されたデータが別々の経路を通って届き、元に組み立てられる。","diagram":{"type":"flow","title":"パケット通信の流れ","items":[{"label":"データを小さく分割する","sub":"分割した単位がパケット"},{"label":"別々の経路を通って届く","sub":"空いている道を選んで送られる"},{"label":"元のデータに組み立て直す","sub":"届いた順に並べ直す"}]}},{"word":"暗号化","text":"データを第三者に読めない形に変換すること。通信の盗み見や改ざんを防ぐ基本的な技術。"},{"word":"認証","text":"利用者が本人であることを確かめること。パスワードのほか、指紋などの生体認証や二要素認証がある。"},{"word":"コンピュータウイルス","text":"コンピュータに害を与える不正なプログラム。感染を防ぐにはセキュリティソフトの更新や不審なファイルを開かないことが大切。"}]},"情報||2進数と情報量":{"points":[{"word":"2進数","text":"0と1の2種類の数字だけで数を表す方法。コンピュータ内部の情報表現の基本。"},{"word":"ビット","text":"情報量の最小単位。0か1かのどちらか一方を表す。","diagram":{"type":"causal","title":"ビットとバイト","items":[{"label":"1ビット","sub":"0か1のどちらか一方を表す最小単位"},{"label":"8ビット＝1バイト","sub":"英数字1文字程度を表せる"}]}},{"word":"バイト","text":"8ビットをまとめた単位。1バイトで英数字1文字程度を表せる。"},{"word":"16進数","text":"0〜9とA〜Fの16種類の記号で数を表す方法。2進数の4桁を1桁にまとめられるため、コンピュータの表記でよく使われる。"},{"word":"文字コード","text":"文字と数字（ビット列）の対応表。UTF-8やShift_JISなどの種類がある。"},{"word":"デジタル化","text":"音や画像などのアナログ情報を、数値の列に変換すること。標本化・量子化・符号化の手順で行われる。","diagram":{"type":"flow","title":"デジタル化の手順","items":[{"label":"標本化","sub":"一定の間隔で値を取り出す"},{"label":"量子化","sub":"取り出した値を段階的な数値に置き換える"},{"label":"符号化","sub":"数値を0と1の列に変換する"}]}}]},"情報||アルゴリズムとプログラミング":{"points":[{"word":"アルゴリズム","text":"問題を解決するための明確な手順。同じ目的でも、手順によって効率が大きく変わることがある。"},{"word":"順次・分岐・反復","text":"プログラムの基本構造。順次は上から順に実行、分岐は条件で処理を選ぶ、反復は同じ処理を繰り返す。","diagram":{"type":"causal","title":"プログラムの基本構造","items":[{"label":"順次","sub":"上から順に実行する"},{"label":"分岐","sub":"条件によって処理を選ぶ"},{"label":"反復","sub":"同じ処理を繰り返す"}]}},{"word":"フローチャート","text":"処理の流れを図記号で表したもの。開始・終了は端子、判断はひし形で表すなどの約束がある。"},{"word":"変数","text":"データを一時的に入れておく箱のようなもの。名前を付けて値を出し入れできる。"},{"word":"探索","text":"データの中から目的のものを探す処理。端から順に探す線形探索や、範囲を半分に絞る二分探索がある。","diagram":{"type":"causal","title":"探索の方法","items":[{"label":"線形探索","sub":"端から順に探す"},{"label":"二分探索","sub":"範囲を半分に絞りながら探す"}]}},{"word":"整列（ソート）","text":"データを大きい順や小さい順に並べ替える処理。バブルソートなどが基本として知られる。"}]},"情報||データの活用":{"points":[{"word":"代表値","text":"データ全体の特徴を一つの値で表したもの。平均値・中央値・最頻値があり、外れ値があるときは中央値が実態を表しやすい。","diagram":{"type":"causal","title":"代表値の種類","items":[{"label":"平均値","sub":"全部の値を足して個数で割った値"},{"label":"中央値","sub":"順に並べたとき真ん中に来る値"},{"label":"最頻値","sub":"最も多く現れる値"}]}},{"word":"散布図と相関","text":"二つの量の関係を点で表したグラフが散布図。点の集まり方から、正の相関・負の相関・相関なしを読み取る。"},{"word":"相関と因果","text":"相関関係があっても、必ずしも一方が原因とは限らない。安易に因果関係と決めつけないことが大切。"},{"word":"ビッグデータ","text":"従来の方法では扱いきれないほど大量で多様なデータ。AIの学習などにも使われる。"},{"word":"データベース","text":"データを整理して蓄え、検索や更新をしやすくした仕組み。表（テーブル）の形で管理する関係データベースが代表的。"},{"word":"オープンデータ","text":"誰でも自由に使える形で公開されたデータ。自治体の統計などがあり、二次利用が進められている。"}]},"情報||情報社会と法律":{"points":[{"word":"個人情報","text":"氏名や生年月日など、特定の個人を識別できる情報。個人情報保護法で取り扱いのルールが定められている。"},{"word":"著作権","text":"著作物を作った人の権利。文章・音楽・画像などは、原則として著作者の許可なく勝手に使えない。"},{"word":"知的財産権","text":"著作権や特許権など、創作や発明に対する権利の総称。人間の知的活動の成果を守る。","diagram":{"type":"causal","title":"知的財産権","items":[{"label":"著作権","sub":"文章・音楽・画像など著作物への権利"},{"label":"特許権など","sub":"発明などへの権利。創作や発明の成果を守る"}]}},{"word":"情報モラル","text":"情報社会で守るべき道徳や心構え。他人への配慮や、法令・ルールの遵守を含む。"},{"word":"フェイクニュース","text":"事実でないのに本当らしく見せた情報。拡散する前に出典を確認する習慣が大切。"},{"word":"デジタルデバイド","text":"情報技術を使える人と使えない人の間に生じる格差のこと。情報格差ともいう。"}]},"体育||安全の確保":{"points":[{"word":"危険の予測と回避","text":"施設・用具の異常、天候の変化、体調の不良など、事故につながる危険を事前に察知し、取り除いたり避けたりすること。安全確保の基本となる考え方。"},{"word":"熱中症","text":"暑い環境で体温調節がうまくいかなくなり、めまい・頭痛・吐き気などを起こす障害。こまめな水分・塩分補給と休憩、WBGT（暑さ指数）を目安にした活動の調整で予防する。"},{"word":"RICE処置","text":"スポーツ外傷の応急処置の原則。安静（Rest）・冷却（Ice）・圧迫（Compression）・挙上（Elevation）の頭文字をとったもの。けがの直後に行うことで悪化を防ぐ。","diagram":{"type":"causal","title":"RICE処置（応急処置の原則）","items":[{"label":"Rest（安静）","sub":"運動をやめて休ませる"},{"label":"Ice（冷却）","sub":"氷などで冷やす"},{"label":"Compression（圧迫）","sub":"包帯などで軽く圧迫する"},{"label":"Elevation（挙上）","sub":"心臓より高く上げる"}]}},{"word":"ウォーミングアップ","text":"運動の前に体を温め、心拍数や筋肉の働きを少しずつ高める準備運動。けがの予防や運動効果の向上に役立つ。運動後のクーリングダウンと対になる。"},{"word":"落雷への対応","text":"雷鳴が聞こえたら屋外の活動をただちに中止し、建物の中など安全な場所に避難する。木の下や高い場所は危険なので避ける。"},{"word":"AED","text":"自動体外式除細動器。心臓が細かく震えて血液を送れない状態のときに電気ショックを与え、正常な動きに戻すための機器。公共施設や学校などに設置されている。"}]},"体育||スポーツ外傷・障害":{"points":[{"word":"スポーツ外傷","text":"一度の大きな外力で起こる急性のけが。捻挫・骨折・脱臼・打撲・肉離れなどが代表例。","diagram":{"type":"causal","title":"外傷と障害の違い","items":[{"label":"スポーツ外傷","sub":"一度の大きな外力で起こる急性のけが（捻挫・骨折など）"},{"label":"スポーツ障害","sub":"使いすぎ（オーバーユース）で起こる慢性の痛み（野球肘など）"}]}},{"word":"スポーツ障害","text":"同じ動作の繰り返しなどによる使いすぎ（オーバーユース）で起こる慢性のけがや痛み。野球肘・テニス肘・シンスプリント・疲労骨折など。"},{"word":"オーバーユース","text":"使いすぎのこと。特定の部位に負荷が繰り返し加わり続けることで、スポーツ障害の主な原因となる。"},{"word":"疲労骨折","text":"一度に折れるほどの力ではなく、弱い力が骨の同じ部位に繰り返し加わることで起こる骨折。ランニングやジャンプの多い競技で起こりやすい。"},{"word":"シンスプリント","text":"すねの内側に痛みが出る代表的なスポーツ障害。走る動作の繰り返しが主な原因で、初心者ランナーなどに多い。"},{"word":"障害の予防","text":"練習量の調整、正しいフォームの習得、筋力・柔軟性の向上、痛みをがまんしないことなどが障害予防の柱になる。"}]},"体育||健康づくりのための運動":{"points":[{"word":"有酸素運動","text":"ウォーキングやジョギングのように、酸素を取り入れながら比較的長く続けられる運動。脂肪をエネルギーとして使いやすく、生活習慣病の予防に役立つ。"},{"word":"身体活動基準","text":"国が示す健康づくりのための目安。18〜64歳では、3メッツ以上の身体活動を毎日60分行うことが勧められている。"},{"word":"メッツ","text":"身体活動の強さを表す単位。安静時を1メッツとし、普通の歩行が3メッツ程度。活動の強さと時間を組み合わせて活動量を考える。"},{"word":"ロコモティブシンドローム","text":"骨・関節・筋肉などの運動器の障害によって、立つ・歩くなどの移動機能が低下した状態。略してロコモ。将来の要介護リスクを高める。"},{"word":"サルコペニア","text":"加齢にともなう筋肉量の減少や筋力の低下。筋力トレーニングと十分なたんぱく質の摂取が予防に役立つ。"},{"word":"メタボリックシンドローム","text":"内臓脂肪の蓄積（腹囲が男性85cm以上・女性90cm以上）に加え、高血糖・脂質異常・高血圧などが重なった状態。生活習慣病のリスクが高い。","diagram":{"type":"causal","title":"メタボリックシンドローム","items":[{"label":"内臓脂肪の蓄積","sub":"腹囲が男性85cm以上・女性90cm以上"},{"label":"さらに重なる状態","sub":"高血糖・脂質異常・高血圧など"},{"label":"生活習慣病のリスクが高い","sub":"早めの対策が必要"}]}}]},"体育||生涯スポーツ":{"points":[{"word":"生涯スポーツ","text":"生涯にわたって、それぞれの年齢・体力・興味に応じてスポーツに親しみ続けること、またその考え方。"},{"word":"する・みる・ささえる","text":"スポーツへの関わり方の3つの形。自分でプレーする「する」、観戦する「みる」、ボランティアや指導などで支える「ささえる」。","diagram":{"type":"causal","title":"スポーツへの関わり方","items":[{"label":"する","sub":"自分でプレーする"},{"label":"みる","sub":"観戦する"},{"label":"ささえる","sub":"ボランティアや指導などで支える"}]}},{"word":"総合型地域スポーツクラブ","text":"地域住民が主体となって運営し、子どもから高齢者までが複数の種目を楽しめるスポーツクラブ。地域のスポーツの受け皿として各地に広がっている。"},{"word":"ライフステージ","text":"人生の段階のこと（少年期・青年期・壮年期・高齢期など）。段階ごとに体力や生活が変わるため、スポーツの形も合わせていく。"},{"word":"スポーツ基本法","text":"スポーツに関する基本的な理念と国の責務などを定めた法律。スポーツを通じて幸福で豊かな生活を営むことを人々の権利としている。"},{"word":"スポーツ庁","text":"国のスポーツ行政を担当する機関。スポーツの振興に関する政策を進めている。"}]},"体育||ライフスタイルに応じたスポーツ":{"points":[{"word":"ライフスタイル","text":"日常生活の送り方や習慣、価値観などの総体。生活様式。スポーツは自分のライフスタイルに合わせて取り入れることで続けやすくなる。"},{"word":"スポーツライフの設計","text":"自分の現状（生活時間・体力・興味）を把握し、目標と計画を立て、実践と見直しを繰り返しながら、自分に合ったスポーツとの関わり方を作っていくこと。","diagram":{"type":"flow","title":"スポーツライフの設計","items":[{"label":"現状を把握する","sub":"生活時間・体力・興味を知る"},{"label":"目標と計画を立てる","sub":"具体的に、少し頑張れば届く水準で"},{"label":"実践と見直しを繰り返す","sub":"自分に合った関わり方を作っていく"}]}},{"word":"現状の把握","text":"設計の出発点。1日の生活時間、体力、健康状態、興味のある種目などを知ること。"},{"word":"目標設定","text":"「週に2回、30分歩く」のように、具体的で、現状から少し頑張れば届く水準の目標を立てることが継続のポイントになる。"},{"word":"すきま時間の活用","text":"徒歩での移動や階段の利用など、日常生活の中の活動を積み重ねて活動量を増やす工夫。まとまった時間がとれない人にも有効。"},{"word":"PDCAサイクル","text":"計画（Plan）・実行（Do）・評価（Check）・改善（Action）を繰り返す進め方。計画の見直しに役立つ。","diagram":{"type":"flow","title":"PDCAサイクル","items":[{"label":"Plan（計画）","sub":"目標と計画を立てる"},{"label":"Do（実行）","sub":"計画に沿って実践する"},{"label":"Check（評価）","sub":"結果を振り返る"},{"label":"Action（改善）","sub":"次の計画に生かす"}]}}]},"体育||スポーツ推進の取り組み":{"points":[{"word":"スポーツ庁","text":"国のスポーツ行政を担当する機関（2015年設置）。スポーツ立国の実現に向けた政策を進めている。"},{"word":"総合型地域スポーツクラブ","text":"地域住民が主体となり、世代をこえて複数の種目を楽しめるクラブ。地域のスポーツ推進の中心的な存在。"},{"word":"スポーツボランティア","text":"大会の運営補助や観客の案内など、スポーツを「ささえる」立場で無償で活動する人。大会の成功に欠かせない。"},{"word":"障がい者スポーツ","text":"障がいのある人が行うスポーツ。推進することで、障がいの有無にかかわらずスポーツを楽しめる共生社会の実現につながる。"},{"word":"スポーツツーリズム","text":"スポーツの観戦や大会への参加を目的とした旅行と、地域の活性化を結びつけた取り組み。"},{"word":"レガシー","text":"大会開催などによって社会に残る遺産のこと。施設だけでなく、人々のスポーツへの関心や参加の広がりも含まれる。"}]},"体育||豊かなスポーツライフの創造":{"points":[{"word":"スポーツの多様な価値","text":"健康の維持・増進、楽しさ、仲間との交流、挑戦と達成感、地域とのつながりなど、スポーツが持つさまざまな価値。"},{"word":"フェアプレイ","text":"ルールを守り、相手や審判を尊重して正々堂々と競う態度。スポーツの土台となる精神。"},{"word":"ドーピング","text":"禁止薬物などを使って競技力を不公正に高める行為。公正さを損ない、健康を害するため厳しく禁止されている。"},{"word":"スポーツと交流","text":"スポーツは共通の楽しみを通じて、年齢・地域・国をこえた人々のつながりや連帯感を生み出す。"},{"word":"スポーツと環境","text":"自然の中で行うスポーツでは、環境を守る責任ある行動が求められる。活動の場を将来に残すこともスポーツライフの一部。"},{"word":"関わり方の変化","text":"年齢や興味の変化に合わせて、「する・みる・ささえる」の比重や種目を選び直していくことで、スポーツライフは豊かに続いていく。"}]},"論理国語||働くということ":{"points":[{"word":"労働と仕事の違い","text":"「労働」が賃金を得るための活動として捉えられがちなのに対し、「仕事」は社会の中での役割や、自分自身の生き方と結びついた営みとして論じられることが多い。"},{"word":"言葉と仕事","text":"働く場面では、指示を理解し、相手に伝え、関係を作るために言葉が欠かせない。言葉は仕事の道具であると同時に、仕事の内容そのものを形作る。"},{"word":"楽しく働く／楽に働く","text":"教科書の文章で対比される視点。「楽（らく）」と「楽しさ」は同じではなく、働くことの価値は楽さだけでは測れない、という論点につながる。"},{"word":"社会との関わり","text":"働くことは、自分のためだけでなく、他者や社会に何かを提供する営みでもある。筆者の主張を読むとき、この視点が根拠として使われやすい。"},{"word":"筆者の主張の追い方","text":"評論では、具体例や対比の後に筆者の主張が置かれることが多い。「つまり」「だから」などの接続語と、段落の役割に注目して読む。"},{"word":"問いを立てる","text":"「なぜ働くのか」という大きな問いを、文章がどの部分でどう答えているかを意識して読む姿勢。評論読解の出発点になる。"}]},"論理国語||論理の力―論理とは何か":{"points":[{"word":"つながる力","text":"文と文、段落と段落のつながり（因果・対比・言い換えなど）を読み取り、文章全体の流れを把握する力。"},{"word":"結論する力","text":"根拠をもとに結論を導く力。前提が正しくても、つなぎ方が誤っていれば結論は成り立たないことに注意する。"},{"word":"整理する力","text":"情報を分類したり、共通点と相違点を見つけたりして、物事を分かりやすく組み立て直す力。図や表への整理も含まれる。"},{"word":"質問する力","text":"文章や主張に対して「なぜか」「本当にそうか」と問いを立て、理解を深めたり問題点を見つけたりする力。"},{"word":"演繹（えんえき）","text":"一般的な前提から、個別の結論を導く推論の方法。例：「すべての人間は死ぬ。ソクラテスは人間である。ゆえにソクラテスは死ぬ。」","diagram":{"type":"flow","title":"演繹の例","items":[{"label":"すべての人間は死ぬ","sub":"一般的な前提"},{"label":"ソクラテスは人間である","sub":"個別の前提"},{"label":"ゆえにソクラテスは死ぬ","sub":"導かれる結論"}]}},{"word":"帰納（きのう）","text":"個別の事例を積み重ねて、一般的な法則や結論を導く推論の方法。事例の数や偏りに注意が必要になる。","diagram":{"type":"flow","title":"帰納の進み方","items":[{"label":"個別の事例","sub":"観察した事実を積み重ねる"},{"label":"共通の傾向","sub":"事例の偏りに注意する"},{"label":"一般的な法則・結論","sub":"広く当てはまる結論を導く"}]}}]},"論理国語||科学と人間":{"points":[{"word":"鏡としての人工知能","text":"人工知能を作る・研究することは、人間の知能や心の仕組みを映し出し、人間とは何かを考え直すきっかけになる、という捉え方。","diagram":{"type":"causal","title":"鏡としての人工知能","items":[{"label":"人工知能を作る・研究する","sub":"人間の知的活動を再現する試み"},{"label":"人間の知能や心が映し出される","sub":"仕組みを考えるほど人間の特徴が見える"},{"label":"人間とは何かを考え直す","sub":"人間観を見直すきっかけになる"}]}},{"word":"人工知能（AI）","text":"人間の知的活動をコンピュータで実現しようとする技術の総称。評論では、技術そのものより、それが人間観に与える影響が論点になることが多い。"},{"word":"ロボットと隣人","text":"ロボットが生活の中に入ってくるとき、人間はそれを道具としてだけでなく、関わりの相手として受け止めるようになる、という問題意識。"},{"word":"人間らしさの条件","text":"感情を持つこと、意識を持つこと、他者と関わることなど、「人間とは何か」をめぐる問いの軸。科学技術の発達によって問い直されている。"},{"word":"技術と倫理","text":"科学技術が可能にすることと、社会として許容できることの間には隔たりがある。評論では両者の関係が論じられる。"},{"word":"比喩の読み取り","text":"「鏡」のような比喩は、筆者の主張の核になることが多い。何を何にたとえ、どんな性質に注目しているかを読み取ることが大切。"}]},"論理国語||言葉と認識":{"points":[{"word":"もの命名","text":"言葉は物に名前（ラベル）を付けるものだ、という考え方。内田樹はこの見方を批判し、言葉の働きはそれだけではないと論じる。"},{"word":"言葉と認識","text":"私たちは言葉を通して世界を切り分け、理解している。使う言葉が変われば、世界の見え方も変わる、という関係。","diagram":{"type":"causal","title":"言葉と認識の関係","items":[{"label":"言葉を通して世界を見る","sub":"言葉で世界を切り分ける"},{"label":"世界の理解のしかたが決まる","sub":"切り分け方によって見え方が変わる"},{"label":"使う言葉が変わると見え方も変わる","sub":"認識は言葉に影響される"}]}},{"word":"科学的発見","text":"未知のものを見つけること。小川眞里子の文章では、発見は単なる「発見」ではなく、既存の知識の枠組みとの関係の中で成り立つことが論じられる。"},{"word":"パラダイム","text":"ある時代の科学者集団が共有する、ものの見方や研究の枠組み。発見の評価はこの枠組みに左右される。"},{"word":"図解の読み解き方","text":"教科書でも扱われる技能。図やグラフが何を示し、何を示していないか、文章とどう対応するかを読み取ること。"},{"word":"常識を疑う","text":"評論の多くは、当たり前だと思われている見方に疑問を投げかけるところから始まる。問いの立て方に注目して読む。"}]},"論理国語||知のゆくえと未来":{"points":[{"word":"知識の作為性","text":"知識は自然にそこにあるのではなく、人間が目的や関心に応じて作り出してきたものだ、という見方。"},{"word":"知識の構造性","text":"知識はばらばらの事実の集まりではなく、互いに関係し合い、体系として組み立てられているという性質。","diagram":{"type":"causal","title":"知識の構造性","items":[{"label":"ばらばらの事実","sub":"個々の知識のかけら"},{"label":"互いに関係し合う","sub":"事実どうしが結びつく"},{"label":"体系として組み立つ","sub":"知識は構造を持っている"}]}},{"word":"もう一つの知性","text":"養老孟司が論じる、論理や計算だけではない知性のあり方。身体や感覚、都市と自然の対比などと結びつけて論じられる。"},{"word":"サピエンス","text":"現生人類（ホモ・サピエンス）のこと。若井京人の文章では、人類がどう自らを作り変えてきたかが論じられる。"},{"word":"未来のありか","text":"若林幹夫の文章の題名。未来はどこか遠くにあるのではなく、現在の私たちの営みの中にある、という問題意識と結びつく。"},{"word":"評論の総まとめの読み方","text":"終盤の文章は、それまでのテーマ（言葉・科学・認識）を踏まえて読むと理解が深まる。各文章の問いと主張を対応させて整理する。"}]},"文学国語||山月記":{"points":[{"word":"李徴（りちょう）","text":"「山月記」の主人公。詩人として名を成そうとしたが挫折し、虎になってしまう。自分の変身の理由を冷静に分析して語る点が特徴。"},{"word":"袁傪（えんさん）","text":"李徴の友人。旅の途中で虎になった李徴と再会し、その告白を聞く聞き手の役割を担う。","diagram":{"type":"causal","title":"李徴と袁傪の関係","items":[{"label":"李徴","sub":"詩人を目指して挫折し、虎になった主人公"},{"label":"袁傪（えんさん）","sub":"旅の途中で再会し、李徴の告白を聞く友人"}]}},{"word":"臆病な自尊心と尊大な羞恥心","text":"李徴が自分を評した言葉。人に頭を下げることを恥とし、才能を世に問う勇気も持てなかった、という自己分析を表す。"},{"word":"虎になるということ","text":"作品の中心的なモチーフ。人間としての心を保ちながら姿が獣になることで、李徴の内面の問題が形になって表れている。"},{"word":"中島敦","text":"「山月記」の作者（1909〜1942）。中国の古典を題材にした作品が多く、格調高い文体で知られる。"},{"word":"一人称の告白","text":"李徴が自分の過去と心情を語る形式。語り手自身の解釈を通して読むため、その言葉をどこまで信じるかも読みどころになる。"}]},"文学国語||こころ":{"points":[{"word":"先生","text":"「こころ」の中心人物。過去のある出来事をきっかけに人を信じられなくなり、孤独を抱えて生きている。"},{"word":"K","text":"先生の学生時代の友人。先生との関係の変化と、その結末が先生の生涯を決定づける。","diagram":{"type":"causal","title":"先生とKと「私」の関係","items":[{"label":"先生","sub":"過去の出来事から人を信じられなくなった中心人物"},{"label":"K","sub":"先生の学生時代の友人。関係の変化と結末が先生の生涯を決めた"},{"label":"「私」","sub":"先生の遺書を受け取り、過去を知る語り手"}]}},{"word":"遺書","text":"先生が「私」に宛てて残した長い手紙。「下 先生と遺書」の中心で、先生の過去と苦悩が明かされる。"},{"word":"エゴイズム","text":"自分の利益や感情を優先する心の働き。「こころ」は、人間のエゴイズムと、それに苦しむ良心を描いた作品として読まれる。"},{"word":"明治の精神","text":"作中で先生が口にする言葉。明治天皇の崩御や乃木大将の殉死と結びつき、時代の転換点としての明治の終わりが描かれる。"},{"word":"夏目漱石","text":"「こころ」の作者（1867〜1916）。『吾輩は猫である』『坊っちゃん』などでも知られる明治・大正の文豪。"}]},"文学国語||檸檬":{"points":[{"word":"梶井基次郎","text":"「檸檬」の作者（1901〜1932）。短い生涯の中で、感覚的で詩情豊かな短編を残した。"},{"word":"えたいの知れない不快の塊","text":"「私」の心を重くする憂鬱な気持ちを表す作中の表現。原因のはっきりしない不快感が作品全体を覆う。"},{"word":"檸檬（レモン）","text":"「私」が果物屋で手に入れる一つの実。その色や重さ、冷たさが「私」の気持ちを一時的に晴らす象徴として描かれる。"},{"word":"丸善","text":"京都の書店。「私」がかつて好んだ場所だが、憂鬱な時期には入ることを避ける。作品の結末の舞台にもなる。"},{"word":"感覚の描写","text":"色・音・重さ・冷たさなど、五感に訴える描写が豊かなことが「檸檬」の文体の特徴。気持ちの変化が感覚を通して表される。"},{"word":"爆弾の比喩","text":"檸檬を丸善の書棚に置いて立ち去る場面で、「私」が空想するたとえ。憂鬱を吹き飛ばしたい気持ちの表れとして読める。"}]},"文学国語||舞姫":{"points":[{"word":"森鷗外","text":"「舞姫」の作者（1862〜1922）。軍医としてドイツに留学した経験を持ち、その体験が作品の土台になっている。"},{"word":"太田豊太郎","text":"「舞姫」の主人公で語り手。エリート官僚として将来を嘱望されながら、エリスとの生活と出世の道の間で揺れる。"},{"word":"エリス","text":"ベルリンの踊り子。貧しい生活の中で豊太郎と出会い、共に暮らすようになる。","diagram":{"type":"causal","title":"豊太郎を取り巻く人々","items":[{"label":"太田豊太郎","sub":"主人公で語り手。出世の道とエリスとの生活の間で揺れる"},{"label":"エリス","sub":"ベルリンの踊り子。豊太郎と共に暮らす"},{"label":"相沢謙吉","sub":"豊太郎の友人。帰国と出世の道を勧める"}]}},{"word":"相沢謙吉","text":"豊太郎の友人。帰国と出世の道を豊太郎に勧め、物語の転換点に関わる人物。"},{"word":"文語体","text":"「舞姫」が書かれた、昔の書き言葉による文体。現代の口語体とは異なる格調が特徴で、教科書では現代語訳とあわせて学ぶこともある。"},{"word":"近代の自我","text":"個人の感情や生き方を大切にしたい気持ちと、国家や社会の期待との対立。「舞姫」は日本の近代文学における自我の問題を早くに描いた作品とされる。"}]},"文学国語||随筆を読む":{"points":[{"word":"随筆（エッセイ）","text":"作者が体験や見聞をもとに、感想や考えを自由な形式で書いた文章。小説のような作り話ではなく、書き手自身の視点が前面に出る。"},{"word":"書き手の視点","text":"随筆では、何を題材に選び、どこに注目するかに作者の個性が表れる。「なぜこの体験を取り上げたのか」を考えることが読みの手がかりになる。"},{"word":"体験と感想","text":"随筆は体験の記録だけではなく、そこから生まれた感想や発見が中心になる。具体的な場面と、作者の言葉の対応を追って読む。"},{"word":"国語から旅立って","text":"温又柔の随筆。複数の言語の間で育った作者が、言葉と自分の居場所について考える文章。"},{"word":"クレールという女","text":"須賀敦子の随筆。イタリアで出会った女性との記憶を通して、人との出会いと別れを静かに描く。"},{"word":"光の窓","text":"小池昌代の随筆。日常の光景から出発して、記憶や感情の広がりを描く文章として教科書に収められている。"}]},"文学国語||戯曲―父と暮せば":{"points":[{"word":"戯曲","text":"舞台で上演するために書かれた作品。登場人物の台詞（セリフ）と、場面や動作を示すト書きで構成される。"},{"word":"井上ひさし","text":"「父と暮せば」の作者（1934〜2010）。小説家・劇作家として、笑いと社会への視点をあわせ持つ作品を多く残した。"},{"word":"美津江","text":"「父と暮せば」の主人公の娘。原爆で父を失い、「自分だけが生き残って幸せになってはいけない」という思いを抱えている。"},{"word":"竹造","text":"美津江の父。原爆で亡くなったが、幽霊として娘の前に現れ、恋を後押ししようとする。"},{"word":"ト書き","text":"戯曲で、台詞以外の、場面の様子や人物の動作・表情などを記した部分。読み手はト書きから舞台の様子を想像する。"},{"word":"原爆文学","text":"原子爆弾の被害と、その後の人々の生を描いた文学の総称。「父と暮せば」は、被爆者の心の傷と回復を描いた作品として読まれる。"}]},"日本史||飛鳥・奈良時代と律令国家":{"points":[{"word":"聖徳太子（厩戸皇子）","text":"推古天皇のもとで摂政となり、十七条の憲法や冠位十二階を定め、天皇中心の国家づくりを進めた。"},{"word":"大化の改新","text":"645年、中大兄皇子と中臣鎌足らが蘇我氏を倒して始めた政治改革。公地公民の方針が示された。"},{"word":"律令","text":"律は刑罰の法、令は政治の仕組みを定めた法。中国の制度を手本に整えられ、大宝律令（701年）で本格的に成立した。"},{"word":"班田収授法","text":"戸籍に登録された人々に口分田を分け与え、死ねば国に返させる制度。律令国家の土地・人民支配の土台となった。","diagram":{"type":"flow","title":"班田収授法のしくみ","items":[{"label":"戸籍に登録する","sub":"人々を国が把握する"},{"label":"口分田を分け与える","sub":"田で稲作をさせる"},{"label":"死ねば国に返す","sub":"土地は国のものという考え方"}]}},{"word":"租・調・庸","text":"律令制の主な税。租は口分田の収穫の約3％の稲、調は地方の特産物、庸は都での労役の代わりに納める布。","diagram":{"type":"causal","title":"租・調・庸（律令制の税）","items":[{"label":"租","sub":"口分田の収穫の約3％の稲"},{"label":"調","sub":"地方の特産物"},{"label":"庸","sub":"都での労役の代わりに納める布"}]}},{"word":"天平文化","text":"奈良時代、唐との交流や仏教の影響を受けて栄えた国際的で華やかな文化。東大寺の大仏や正倉院の宝物が代表例。"}]},"日本史||平安時代と摂関政治":{"points":[{"word":"平安遷都","text":"794年、桓武天皇が都を平安京（京都）に移したこと。奈良時代の仏教勢力の影響を避ける目的もあったとされる。"},{"word":"摂関政治","text":"藤原氏が、天皇が幼いときは摂政、成人後は関白として政治の実権を握った政治の形。藤原道長・頼通のころに全盛となった。","diagram":{"type":"causal","title":"摂関政治のしくみ","items":[{"label":"天皇が幼いとき","sub":"藤原氏が摂政として補佐する"},{"label":"天皇が成人した後","sub":"藤原氏が関白として補佐する"},{"label":"藤原氏が実権を握る","sub":"道長・頼通のころに全盛"}]}},{"word":"藤原道長","text":"摂関政治の全盛期を築いた人物。「この世をば わが世とぞ思う 望月の…」の歌でも知られる。"},{"word":"国風文化","text":"遣唐使の停止（894年）などを背景に、日本の風土や感性に合った独自の文化。かな文字の発達がその土台となった。"},{"word":"かな文字","text":"漢字をもとに作られた日本独自の文字。ひらがな・カタカナの発達によって、日本語の文章や文学が大きく広がった。"},{"word":"源氏物語と枕草子","text":"紫式部『源氏物語』は長編物語、清少納言『枕草子』は随筆の代表作。宮廷に仕えた女性たちによって国風文化の文学が花開いた。"}]},"日本史||室町時代と戦国への歩み":{"points":[{"word":"足利尊氏と室町幕府","text":"足利尊氏が京都に開いた幕府（1338年ごろ成立）。鎌倉幕府と比べ、将軍の力は守護大名の力に依存する面が大きかった。"},{"word":"南北朝の動乱","text":"後醍醐天皇の吉野の朝廷（南朝）と、足利氏の支える京都の朝廷（北朝）が対立した時代。1392年に南北朝は合一された。","diagram":{"type":"timeline","title":"南北朝の動乱と合一","items":[{"label":"南朝（吉野）と北朝（京都）が対立","sub":"二つの朝廷が並び立つ"},{"label":"1392年 南北朝の合一","sub":"対立が終わる"}]}},{"word":"足利義満と日明貿易","text":"3代将軍足利義満は明との勘合貿易を始め、北山文化を築いた。金閣（鹿苑寺金閣）がその象徴。"},{"word":"応仁の乱","text":"1467年に始まった内乱。守護大名同士の対立と将軍家の後継争いが重なり、京都を戦場にした。この乱の後、将軍の権威は大きく衰えた。"},{"word":"下剋上","text":"身分の低い者が実力で上の者を倒して地位を奪う風潮。戦国時代を象徴する言葉。"},{"word":"東山文化","text":"8代将軍足利義政のころの文化。銀閣、書院造、茶の湯や生け花のもとになる要素など、簡素で深みのある美意識が特徴。"}]},"日本史||江戸時代の社会と改革":{"points":[{"word":"身分制度","text":"武士・百姓・町人などの身分が定められ、武士が支配層として政治を担ったしくみ。実際には身分の内側にも多様な立場があった。"},{"word":"村請制と五人組","text":"村ごとに税（年貢）をまとめて納めさせる村請制と、百姓同士が連帯責任を負う五人組の制度。村の自治と統制の両面を持った。","diagram":{"type":"causal","title":"村請制と五人組","items":[{"label":"村請制","sub":"村ごとに年貢をまとめて納めさせる"},{"label":"五人組","sub":"百姓同士が連帯責任を負うしくみ"}]}},{"word":"享保の改革","text":"8代将軍徳川吉宗の改革。目安箱の設置、上米の制、公事方御定書の制定などを行い、幕府財政の立て直しを図った。"},{"word":"田沼意次と寛政の改革","text":"田沼意次は商業を重視して財政の改善を図ったが、わいろ政治への批判も受けた。その後の松平定信の寛政の改革は、倹約と風紀の取り締まりを進めた。"},{"word":"天保の改革","text":"水野忠邦による改革。株仲間の解散や人返し令などを出したが、十分な成果を上げられず、幕府の衰えをあらわす結果となった。"},{"word":"化政文化","text":"江戸時代後期、江戸を中心に栄えた町人文化。歌川広重や葛飾北斎の浮世絵、川柳や滑稽本などが広く親しまれた。"}]},"日本史||立憲政治と日清・日露戦争":{"points":[{"word":"大日本帝国憲法","text":"1889年発布の明治憲法。天皇が主権者とされ、国民の権利は「法律の留保」のもとで認められた。"},{"word":"帝国議会","text":"貴族院と衆議院からなる議会。1890年に開設された。当初の衆議院議員の選挙権は、直接国税15円以上を納める25歳以上の男性に限られた。"},{"word":"条約改正","text":"幕末に結ばれた不平等条約の改正。1894年に領事裁判権の撤廃、1911年に関税自主権の回復を達成した。","diagram":{"type":"timeline","title":"条約改正の達成","items":[{"label":"1894年 領事裁判権の撤廃","sub":"不平等条約の改正が進む"},{"label":"1911年 関税自主権の回復","sub":"条約改正が完成する"}]}},{"word":"日清戦争","text":"1894〜95年、朝鮮半島の支配をめぐる日本と清の戦争。下関条約で日本は遼東半島・台湾などを得たが、三国干渉で遼東半島は返還した。"},{"word":"日露戦争","text":"1904〜05年、満州と朝鮮の権益をめぐる日本とロシアの戦争。ポーツマス条約で講和したが、日本は賠償金を得られなかった。"},{"word":"産業革命の進展","text":"日清戦争前後から軽工業、日露戦争前後には重工業も発展し、日本の資本主義が本格化した時期。"}]},"日本史||大正デモクラシーと両大戦間期":{"points":[{"word":"大正デモクラシー","text":"大正時代を中心に広がった、民主主義を求める思想や運動の総称。吉野作造の民本主義がその代表的な理論。"},{"word":"政党内閣","text":"議会で多数を占める政党の党首が内閣を組織する政治の形。原敬内閣（1918年）が本格的な政党内閣の始まりとされる。"},{"word":"普通選挙法","text":"1925年成立。納税額による制限がなくなり、25歳以上の男性に選挙権が与えられた。ただし女性にはまだ選挙権がなかった。","diagram":{"type":"causal","title":"1925年の二つの法律","items":[{"label":"普通選挙法（1925年）","sub":"25歳以上の男性に選挙権が広がる"},{"label":"治安維持法（同年）","sub":"天皇制などを否定する運動を取り締まる"}]}},{"word":"治安維持法","text":"普通選挙法と同年に制定された法律。天皇制や私有財産制を否定する運動を取り締まるもので、後に思想弾圧の道具となっていった。"},{"word":"世界恐慌","text":"1929年、アメリカの株価暴落から始まった世界的な不況。日本では昭和恐慌として、農村や都市の生活を直撃した。"},{"word":"大衆文化の広がり","text":"ラジオ放送の開始、映画、雑誌など、都市を中心に大衆向けの文化が広がった時期。生活様式も大きく変化した。"}]},"日本史||戦後の復興と高度経済成長":{"points":[{"word":"サンフランシスコ平和条約","text":"1951年に調印された講和条約。翌1952年に発効し、日本は独立を回復した。同時に日米安全保障条約も結ばれた。","diagram":{"type":"timeline","title":"独立の回復","items":[{"label":"1951年 サンフランシスコ平和条約に調印","sub":"講和が決まる"},{"label":"1952年 条約が発効","sub":"日本が独立を回復する"}]}},{"word":"朝鮮戦争と特需","text":"1950年に始まった朝鮮戦争で、アメリカ軍向けの物資の注文（特需）が日本経済の復興を後押しした。"},{"word":"高度経済成長","text":"1950年代半ばから1970年代初めまでの、年平均10％前後の高い経済成長が続いた時期。鉄鋼・造船・自動車・家電などの産業が発展した。"},{"word":"三種の神器と3C","text":"高度成長期に普及した家電製品の呼び名。白黒テレビ・洗濯機・冷蔵庫が「三種の神器」、後にカラーテレビ・クーラー・自動車が「3C」と呼ばれた。","diagram":{"type":"causal","title":"あこがれの品の移り変わり","items":[{"label":"三種の神器","sub":"白黒テレビ・洗濯機・冷蔵庫"},{"label":"3C","sub":"カラーテレビ・クーラー・自動車"}]}},{"word":"公害問題","text":"経済成長の影で深刻化した、水俣病・四日市ぜんそくなどの公害。1967年に公害対策基本法が制定され、四大公害裁判でも争われた。"},{"word":"石油危機（オイルショック）","text":"1973年、石油価格の急騰によって世界経済が混乱した出来事。日本の高度経済成長はこの時期に終わりを迎えた。"}]},"世界史||古代文明の出現":{"points":[{"word":"農耕の始まり","text":"約1万年前、西アジアで始まったとされる。食料生産の開始は定住生活を生み、社会の分業や格差の出発点となった。","diagram":{"type":"causal","title":"農耕の始まりがもたらした変化","items":[{"label":"農耕の開始（約1万年前）","sub":"西アジアで食料生産が始まる"},{"label":"定住生活が生まれる","sub":"食料を蓄えられるようになる"},{"label":"分業や格差の出発点","sub":"社会の仕組みが複雑になる"}]}},{"word":"メソポタミア文明","text":"ティグリス川とユーフラテス川の流域に生まれた文明。楔形文字、ハンムラビ法典、太陰暦や六十進法で知られる。"},{"word":"エジプト文明","text":"ナイル川の定期的な氾濫を利用した文明。ファラオを頂点とする統一国家が長く続き、ピラミッドや太陽暦を残した。"},{"word":"インダス文明","text":"インダス川流域の都市文明。モヘンジョ＝ダロなどの計画都市と、整った排水設備が特徴。文字はまだ解読されていない。"},{"word":"黄河文明と殷","text":"黄河流域では仰韶文化などを経て、殷（商）が成立。青銅器と漢字のもとになる甲骨文字が使われた。"},{"word":"文明の共通点","text":"大河流域に生まれ、灌漑農業、文字、金属器、都市と国家の形成という共通の要素を持つ点が比較のポイントになる。","diagram":{"type":"causal","title":"古代文明の共通点","items":[{"label":"大河の流域に生まれる","sub":"灌漑農業が発達する"},{"label":"文字・金属器が使われる","sub":"記録と道具の発達"},{"label":"都市と国家が形成される","sub":"文明に共通する要素"}]}}]},"世界史||イスラーム世界の成立と拡大":{"points":[{"word":"ムハンマド","text":"イスラーム教の開祖（預言者）。メッカで迫害を受け、622年にメディナへ移住した（ヒジュラ）。この年がイスラーム暦の元年となる。"},{"word":"コーランと六信五行","text":"聖典はコーラン（クルアーン）。信仰の基本は、唯一神アッラーへの信仰や礼拝・喜捨・断食・巡礼などの五行とされる実践。"},{"word":"カリフ","text":"預言者の後継者としてイスラーム共同体（ウンマ）を率いる指導者の称号。正統カリフ時代の後、ウマイヤ朝が世襲化した。"},{"word":"ウマイヤ朝","text":"ダマスカスを都とした王朝（661〜750）。イベリア半島まで領土を広げたが、アラブ人優遇への不満が高まった。","diagram":{"type":"timeline","title":"イスラーム世界の王朝の流れ","items":[{"label":"ウマイヤ朝（661〜750）","sub":"ダマスカスを都としイベリア半島まで拡大"},{"label":"アッバース朝（750〜1258）","sub":"バグダードを都とし交易と学問の中心に"}]}},{"word":"アッバース朝","text":"バグダードを都とした王朝（750〜1258）。イスラーム世界の交易と学問の中心となり、『千夜一夜物語』の舞台としても知られる。"},{"word":"拡大の背景","text":"ビザンツ帝国とサーサーン朝ペルシアの衰え、被支配層への寛容さや税制などが、急速な拡大を支えたとされる。"}]},"世界史||南アジアと東南アジアの世界":{"points":[{"word":"グプタ朝","text":"4〜6世紀の北インドの王朝。ヒンドゥー教が社会の中心となり、サンスクリット文学や数学（ゼロの概念）などが発展した。"},{"word":"ヒンドゥー教の形成","text":"バラモン教が民間信仰と結びついて成立したインドの宗教。カースト制と結びつき、人々の生活に深く根づいた。"},{"word":"デリー＝スルタン朝","text":"13世紀に北インドに成立したイスラーム王朝。イスラーム教がインドに広がるきっかけとなった。"},{"word":"シュリーヴィジャヤ","text":"スマトラ島を中心にマラッカ海峡の交易を支配した海の王国。海運の要地を押さえて繁栄した。"},{"word":"アンコール朝","text":"カンボジアに栄えた王朝。アンコール＝ワットに代表される壮大なヒンドゥー・仏教建築を残した。"},{"word":"海の道と交易","text":"東南アジアは香辛料などの産地であり、インド洋と南シナ海を結ぶ中継地。交易を通じてインドや中国の文化が伝わり、地域の文化と融合した。","diagram":{"type":"causal","title":"海の道と文化の交流","items":[{"label":"インド洋と南シナ海を結ぶ中継地","sub":"香辛料などの交易で栄える"},{"label":"インドや中国の文化が伝わる","sub":"交易を通じて文化が移動する"},{"label":"地域の文化と融合する","sub":"東南アジア独自の文化が生まれる"}]}}]},"世界史||モンゴル帝国とユーラシア":{"points":[{"word":"チンギス＝ハン","text":"1206年にモンゴル民族を統一し、帝国を築いた指導者。優れた軍事組織と人材登用で急速に版図を広げた。"},{"word":"モンゴル帝国の拡大","text":"西夏・金への遠征に始まり、中央アジアや東ヨーロッパにまで及んだ。駅伝制（ジャムチ）の整備が広大な支配を支えた。","diagram":{"type":"causal","title":"モンゴル帝国の拡大と支配","items":[{"label":"優れた軍事組織と人材登用","sub":"チンギス＝ハンが版図を広げる"},{"label":"中央アジアや東ヨーロッパまで拡大","sub":"広大な帝国になる"},{"label":"駅伝制（ジャムチ）の整備","sub":"広い支配を支える仕組み"}]}},{"word":"4ハン国","text":"帝国が分裂してできた、キプチャク＝ハン国、チャガタイ＝ハン国、イル＝ハン国、オゴタイ＝ハン国などの諸国家。"},{"word":"元（フビライ）","text":"チンギス＝ハンの孫フビライが建てた王朝（1271年国号を元とする）。南宋を滅ぼして中国を統一し、大都（北京）を都とした。"},{"word":"元の日本遠征","text":"1274年と1281年の二度にわたる元軍の襲来（元寇）。いずれも暴風雨などの影響もあって失敗に終わった。"},{"word":"ユーラシアの交流","text":"帝国の支配のもとで東西の交易路が結ばれ、物産・技術・宗教などが大陸規模で移動した。マルコ＝ポーロの旅行記もこの時代のもの。"}]},"世界史||主権国家体制と宗教改革":{"points":[{"word":"ルターの宗教改革","text":"1517年、ルターが「九十五か条の論題」を発表し、贖宥状（免罪符）の販売を批判。信仰のみ・聖書のみを掲げ、プロテスタントが生まれた。","diagram":{"type":"flow","title":"ルターの宗教改革","items":[{"label":"1517年 九十五か条の論題","sub":"贖宥状（免罪符）の販売を批判"},{"label":"信仰のみ・聖書のみを掲げる","sub":"カトリック教会への改革要求"},{"label":"プロテスタントが生まれる","sub":"新しい教会の誕生"}]}},{"word":"カルヴァンと予定説","text":"ジュネーヴで神政政治を行ったカルヴァンの改革。救済はあらかじめ定められているとする予定説を説き、勤勉な生活が重視された。"},{"word":"イギリス国教会","text":"ヘンリ8世が離婚問題をきっかけにカトリック教会から離脱して成立した教会。国王を首長とした。"},{"word":"対抗宗教改革","text":"カトリック側の改革運動。トリエント公会議で教義を明確化し、イエズス会などが布教と教育に力を入れた。"},{"word":"三十年戦争","text":"1618〜48年、神聖ローマ帝国内の宗教対立から始まり、ヨーロッパ諸国を巻き込んだ戦争。多くの被害を出した。","diagram":{"type":"timeline","title":"三十年戦争とその後","items":[{"label":"1618〜48年 三十年戦争","sub":"宗教対立から始まり諸国を巻き込む"},{"label":"1648年 ウェストファリア条約","sub":"主権国家体制の出発点になる"}]}},{"word":"ウェストファリア条約","text":"1648年の講和条約。各国が対等な主権を持つとする主権国家体制の出発点とされ、宗教への不干渉も確認された。"}]},"世界史||世界市場の形成と植民地化":{"points":[{"word":"産業資本主義","text":"産業革命後の資本主義の段階。工場制機械工業を基盤に、資本の蓄積と市場の拡大が進んだ。"},{"word":"インド大反乱とイギリス領インド","text":"1857年の大反乱（セポイの乱）の後、東インド会社は解散し、インドはイギリスの直接統治下に置かれた。"},{"word":"アヘン戦争","text":"1840〜42年と1856〜60年の二度にわたる戦争。清は敗れて開港と不平等条約を強いられ、半植民地化が進んだ。","diagram":{"type":"timeline","title":"アヘン戦争","items":[{"label":"1840〜42年 第一次アヘン戦争","sub":"清が敗れて開港を強いられる"},{"label":"1856〜60年 第二次アヘン戦争","sub":"半植民地化が進む"}]}},{"word":"オスマン帝国の改革","text":"西アジアでは、オスマン帝国がタンジマートと呼ばれる西洋化改革を進めたが、列強の圧力のもとで領土を失っていった。"},{"word":"アフリカ分割","text":"19世紀末、ヨーロッパ列強がアフリカ大陸を短期間のうちに植民地として分割した動き。ベルリン会議（1884〜85）でそのルールが話し合われた。"},{"word":"民族運動の始まり","text":"植民地化への抵抗として、インド国民会議の結成（1885）など、独立を求める民族運動が各地で生まれた。"}]},"世界史||第二次世界大戦":{"points":[{"word":"ファシズムの台頭","text":"イタリアのムッソリーニ、ドイツのヒトラー（ナチス）など、独裁と民族主義を掲げる運動が恐慌後の不安の中で支持を広げた。"},{"word":"第二次世界大戦の開始","text":"1939年9月、ドイツがポーランドに侵攻し、英仏がドイツに宣戦布告して戦争が始まった。"},{"word":"日中戦争と太平洋戦争","text":"1937年に始まった日中戦争は長期化し、1941年に日本が真珠湾を攻撃して太平洋戦争が始まった。"},{"word":"ミッドウェー海戦とスターリングラード","text":"1942〜43年ごろの戦局の転換点。太平洋ではミッドウェー海戦、ヨーロッパ東部戦線ではスターリングラードの戦いが転機となった。","diagram":{"type":"causal","title":"戦局の転換点（1942〜43年）","items":[{"label":"ミッドウェー海戦","sub":"太平洋での転機"},{"label":"スターリングラードの戦い","sub":"ヨーロッパ東部戦線での転機"}]}},{"word":"連合国の戦後構想","text":"大西洋憲章（1941）やヤルタ会談（1945）など、戦争のさなかから戦後の国際秩序の設計が進められた。","diagram":{"type":"timeline","title":"連合国の戦後構想","items":[{"label":"1941年 大西洋憲章","sub":"戦後の秩序の原則を示す"},{"label":"1945年 ヤルタ会談","sub":"戦後処理の話し合い"}]}},{"word":"戦争の終結","text":"1945年、ドイツの降伏と、日本のポツダム宣言受諾によって戦争は終わった。一般市民を含む膨大な犠牲を出した戦争だった。"}]},"世界史||冷戦とその終結":{"points":[{"word":"冷戦","text":"米ソ両陣営が、直接の全面戦争を避けながら対立し続けた状態。核兵器の存在が全面戦争を抑止する一方、各地で代理戦争が起こった。"},{"word":"NATOとワルシャワ条約機構","text":"西側の軍事同盟がNATO（北大西洋条約機構、1949）、東側がワルシャワ条約機構（1955）。両陣営の対立を象徴する組織。","diagram":{"type":"causal","title":"冷戦下の両陣営","items":[{"label":"西側：NATO（1949年）","sub":"北大西洋条約機構"},{"label":"東側：ワルシャワ条約機構（1955年）","sub":"東側の軍事同盟"}]}},{"word":"朝鮮戦争","text":"1950〜53年、朝鮮半島で南北が激突した戦争。アメリカ軍中心の国連軍と、中国の義勇軍が介入し、休戦協定のまま分断が固定された。"},{"word":"キューバ危機","text":"1962年、ソ連がキューバに核ミサイルを配備しようとして米ソが一触即発となった危機。交渉によって回避され、緊張緩和のきっかけにもなった。"},{"word":"ベトナム戦争","text":"アメリカが深く介入した戦争（本格介入は1960年代〜1975）。アメリカの敗北に終わり、その威信を大きく傷つけた。"},{"word":"冷戦の終結","text":"ゴルバチョフのペレストロイカ、1989年の東欧革命とベルリンの壁の崩壊、マルタ会談を経て、1991年にソ連が解体し冷戦は終わった。","diagram":{"type":"timeline","title":"冷戦の終結","items":[{"label":"1989年 ベルリンの壁の崩壊","sub":"東欧革命が進む"},{"label":"1991年 ソ連の解体","sub":"冷戦が終わる"}]}}]},"世界史||グローバル化と現代の課題":{"points":[{"word":"グローバル化","text":"経済・文化・情報などが国境をこえて結びつき、相互依存が深まる動き。多国籍企業の活動や情報通信技術の発達が支えている。"},{"word":"WTOと自由貿易","text":"世界貿易機関（WTO、1995年発足）は自由貿易のルールを担う国際機関。地域経済統合（EUやASEANなど）も並行して進んだ。"},{"word":"南北問題と格差","text":"先進国と発展途上国の経済格差の問題。グローバル化の中でも格差の是正は大きな課題であり続けている。"},{"word":"地球環境問題","text":"地球温暖化、森林の減少、生物多様性の喪失など。パリ協定（2015）のように、国際的な協力の枠組みが作られている。"},{"word":"地域紛争と難民","text":"冷戦後も民族・宗教対立などによる紛争は続き、多くの難民が生まれている。人道支援と平和構築が課題となる。"},{"word":"SDGs","text":"持続可能な開発目標（2015年国連採択）。貧困や環境など17の目標を掲げ、2030年までの達成を目指す国際的な枠組み。"}]},"倫理||人間の心のあり方":{"points":[{"word":"ホモ・サピエンスとホモ・ファーベル","text":"人間を表す言葉。ホモ・サピエンスは「知恵のある人」、ホモ・ファーベルは「作る人（工作人）」。道具の使用や言語が人間の特質とされる。"},{"word":"青年期の課題","text":"自分とは何かを問い（アイデンティティの確立）、親や社会の価値観を見直しながら、自立した自分の生き方を模索する時期の課題。","diagram":{"type":"flow","title":"青年期の課題の進み方","items":[{"label":"自分とは何かを問う","sub":"アイデンティティの確立が中心の課題"},{"label":"親や社会の価値観を見直す","sub":"これまでの当たり前を考え直す"},{"label":"自立した自分の生き方を模索する","sub":"自分らしい生き方を探す"}]}},{"word":"アイデンティティ","text":"「自分は自分である」という自己同一性の感覚。青年期の中心的な発達課題とされる（エリクソン）。"},{"word":"認知","text":"物事を知覚し、記憶し、考える心の働き。同じ出来事でも、認知のしかたによって受け止め方が変わる。"},{"word":"感情と知性","text":"感情は価値判断や行動の原動力となり、知性（理性）はそれを吟味し方向づける。両者のバランスが心のあり方を形作る。"},{"word":"発達","text":"人は生涯を通じて変化し続けるという見方。各時期に特有の課題（発達課題）があり、それに向き合うことで成長していく。"}]},"倫理||中国の思想":{"points":[{"word":"孔子と仁・礼","text":"儒家の開祖孔子は、思いやりの心である「仁」を内面の徳とし、それを社会の形にした「礼」を重んじた。『論語』にその言葉が残る。"},{"word":"儒教の展開","text":"漢の時代に国の教えとして採用され、科挙を通じて官僚の思想となり、やがて朝鮮や日本にも伝わって社会の規範となった。"},{"word":"孟子の性善説","text":"人間の本性は善であり、誰もが仁義の心の芽（四端）を持つとする考え方。王道政治と易姓革命の思想でも知られる。","diagram":{"type":"causal","title":"性善説と性悪説の対比","items":[{"label":"孟子の性善説","sub":"本性は善。誰もが仁義の心の芽（四端）を持つ"},{"label":"荀子の性悪説","sub":"本性は悪に向かいやすいが、学びと礼で正せる"}]}},{"word":"荀子の性悪説","text":"人間の本性は悪に向かいやすいが、学びと礼によって正すことができる（化性起偽）とする考え方。孟子と対比される。"},{"word":"老子の無為自然","text":"人為的な行いを離れ、自然の流れにまかせる生き方（無為自然）を理想とした。『老子』（道徳経）にまとめられた。"},{"word":"荘子の万物斉同","text":"あらゆる物事の区別や価値は相対的であり、絶対的な視点から見れば等しいとする考え方。自由な境地（逍遥遊）を説いた。"}]},"倫理||社会変革の思想と現代思想":{"points":[{"word":"功利主義","text":"行為の善悪を、その行為がもたらす幸福（快楽と苦痛の差）で判断する考え方。ベンサムの「最大多数の最大幸福」が有名。","diagram":{"type":"flow","title":"功利主義の判断のしかた","items":[{"label":"行為がもたらす結果を見る","sub":"幸福（快楽と苦痛の差）を測る"},{"label":"多くの人の幸福が大きいか","sub":"最大多数の最大幸福が基準"},{"label":"行為の善悪を判断する","sub":"結果の幸福の量で決める"}]}},{"word":"ミルの功利主義","text":"J.S.ミルは、快楽には質の違いがあるとし、自由の尊重とあわせて功利主義を発展させた。『自由論』でも知られる。"},{"word":"社会主義思想","text":"生産手段の私有による格差や貧困を批判し、社会全体で富を分かち合う仕組みを目指す思想。マルクスの科学的社会主義が代表的。"},{"word":"実証主義","text":"コントが唱えた、観察と経験に基づく科学的な知識だけを確実なものとする考え方。社会学の出発点にもなった。"},{"word":"実存主義","text":"サルトルらが唱えた、人間はまず存在し、自分の選択と行動によって自分自身を作っていくとする考え方。「実存は本質に先立つ」が有名。"},{"word":"構造主義","text":"レヴィ＝ストロースらが展開した、人間の文化や思考の背後には無意識の構造があるとする考え方。現代思想に大きな影響を与えた。"}]},"倫理||現代の諸課題と倫理":{"points":[{"word":"生命倫理","text":"脳死と臓器移植、安楽死、出生前診断など、医療と生命をめぐる倫理的な問題を扱う分野。本人の意思（インフォームド・コンセント）が重視される。"},{"word":"環境倫理","text":"自然や将来世代に対する人間の責任を考える倫理。「将来世代への配慮」「自然の生存権」「地球全体を考える」などの原則が論じられる。","diagram":{"type":"causal","title":"環境倫理の原則","items":[{"label":"将来世代への配慮","sub":"未来の人々への責任"},{"label":"自然の生存権","sub":"自然にも生きる権利がある"},{"label":"地球全体を考える","sub":"人間中心から地球全体の視点へ"}]}},{"word":"科学技術と倫理","text":"AIや遺伝子技術など、できることが増えるほど「やってよいか」を問う必要が生まれる。ヨーナスの責任倫理などが知られる。"},{"word":"福祉と正義","text":"社会保障や富の分配をどうすれば公正と言えるか。ロールズの「公正としての正義」などが、考える枠組みとして用いられる。"},{"word":"多文化共生","text":"文化や宗教の異なる人々が、互いの違いを認め合いながら共に生きること。現代の多様な社会における倫理の課題。"},{"word":"平和の実現","text":"戦争のない状態だけでなく、貧困や差別などの構造的暴力をなくす「積極的平和」（ガルトゥング）という考え方も重要になる。","diagram":{"type":"causal","title":"二つの平和の考え方","items":[{"label":"消極的平和","sub":"戦争のない状態"},{"label":"積極的平和","sub":"貧困や差別などの構造的暴力もない状態（ガルトゥング）"}]}}]},"政治・経済||民主政治の基本原理":{"points":[{"word":"国民主権","text":"国の政治のあり方を最終的に決める力（主権）は国民にあるという原理。民主政治の根本となる考え方。"},{"word":"社会契約説","text":"人々が契約によって国家を作ったとする考え方。ホッブズ、ロック、ルソーがそれぞれの立場から論じ、民主政治の理論的な土台となった。","diagram":{"type":"causal","title":"社会契約説を論じた人々","items":[{"label":"ホッブズ","sub":"社会契約説を論じた一人"},{"label":"ロック","sub":"社会契約説を論じた一人"},{"label":"ルソー","sub":"社会契約説を論じた一人"}]}},{"word":"権力分立","text":"国家の権力を立法・行政・司法に分け、互いに抑制し合うことで権力の乱用を防ぐ仕組み。モンテスキューが唱えた。"},{"word":"法の支配","text":"人も権力者も法に従うべきだという考え方。権力者の気まぐれな支配（人の支配）と対比される。"},{"word":"基本的人権の確立","text":"自由権を中心に、人権保障は市民革命を通じて確立され、やがて社会権なども含むようになった。"},{"word":"政治体制の違い","text":"民主主義体制のほか、権威主義体制や全体主義体制などがある。意思決定の方法と人権保障の有無が大きな違いになる。"}]},"政治・経済||財政のしくみ":{"points":[{"word":"財政の役割","text":"資源配分の調整（公共財の提供）、所得の再分配、景気の安定化の3つが財政の代表的な役割とされる。","diagram":{"type":"causal","title":"財政の三つの役割","items":[{"label":"資源配分の調整","sub":"公共財を提供する"},{"label":"所得の再分配","sub":"格差をやわらげる"},{"label":"景気の安定化","sub":"好況・不況の波を抑える"}]}},{"word":"直接税と間接税","text":"税を負担する人と納める人が同じなのが直接税（所得税など）、異なるのが間接税（消費税など）。両者のバランスが議論になる。"},{"word":"累進課税","text":"所得が多い人ほど高い税率が適用される仕組み。所得の再分配の役割を持つ。"},{"word":"予算と国会の議決","text":"政府が作る予算案は国会の議決を経て成立する。財政民主主義の表れであり、衆議院の優越も認められている。"},{"word":"公債（国債）","text":"国の支出が税収でまかなえないときに発行する借金。建設国債と、歳入不足を補う特例国債（赤字国債）がある。","diagram":{"type":"causal","title":"公債（国債）の種類","items":[{"label":"建設国債","sub":"公共事業などのために発行する"},{"label":"特例国債（赤字国債）","sub":"歳入の不足を補うために発行する"}]}},{"word":"財政の健全化","text":"公債残高の増大は将来世代への負担となるため、歳出の見直しや成長戦略などを通じて財政を立て直すことが課題となっている。"}]},"政治・経済||日本経済の発展と課題":{"points":[{"word":"高度経済成長","text":"1950年代半ばから1970年代初めまで続いた急速な経済成長。技術革新と設備投資、輸出の拡大が支えた。"},{"word":"バブル経済とその崩壊","text":"1980年代後半、地価や株価が実体以上に膨らんだバブル経済が1990年代初めに崩壊し、長期の景気低迷（失われた時代）につながった。","diagram":{"type":"timeline","title":"バブル経済とその後","items":[{"label":"1980年代後半 バブル経済","sub":"地価や株価が実体以上に膨らむ"},{"label":"1990年代初め 崩壊","sub":"バブルがはじける"},{"label":"長期の景気低迷","sub":"「失われた時代」と呼ばれる"}]}},{"word":"中小企業の課題","text":"日本企業の大半を占める中小企業は、大企業との生産性や賃金の格差、後継者不足などの課題を抱えている。"},{"word":"雇用と労働問題","text":"終身雇用や年功賃金といった日本的雇用慣行が変化し、非正規雇用の拡大、長時間労働、男女の格差などが課題となっている。"},{"word":"社会保障制度","text":"社会保険（医療・年金・介護など）、公的扶助、社会福祉、公衆衛生からなる、人々の生活を支える仕組み。","diagram":{"type":"causal","title":"社会保障制度の四つの柱","items":[{"label":"社会保険","sub":"医療・年金・介護など"},{"label":"公的扶助","sub":"生活に困る人を助ける"},{"label":"社会福祉","sub":"支援が必要な人を支える"},{"label":"公衆衛生","sub":"人々の健康を守る"}]}},{"word":"少子高齢化と社会保障","text":"現役世代の負担が重くなる中で、給付と負担のバランスをどう保つかが、社会保障の最大の課題となっている。"}]},"政治・経済||国際政治と国際連合":{"points":[{"word":"国際政治の特質","text":"国内政治と違い、世界全体を治める政府が存在しない。そのため、国家間の力関係や外交、国際法が重要な役割を果たす。"},{"word":"国際法","text":"条約と国際慣習法を主な法源とする、国家間の関係を規律する法。国内法のような強制力を持たない面もある。"},{"word":"国際連合の設立","text":"1945年、第二次世界大戦の反省から設立された国際機関。平和の維持と国際協力の推進を目的とする。"},{"word":"安全保障理事会","text":"国際の平和と安全の維持に主要な責任を持つ機関。アメリカ・イギリス・フランス・ロシア・中国の5常任理事国には拒否権がある。","diagram":{"type":"causal","title":"安全保障理事会","items":[{"label":"平和と安全の維持に主要な責任","sub":"国連の中で中心的な機関"},{"label":"5常任理事国","sub":"アメリカ・イギリス・フランス・ロシア・中国。拒否権を持つ"}]}},{"word":"PKO（平和維持活動）","text":"停戦の監視や選挙の支援などを行う国連の活動。日本も1992年のPKO協力法以降、要員を派遣してきた。"},{"word":"国際連合の課題","text":"常任理事国の拒否権による機能不全の指摘や、安保理の構成が現在の世界を反映していないという改革論議がある。"}]},"政治・経済||国際経済とグローバル化":{"points":[{"word":"貿易の利益と比較優位","text":"各国が得意な財の生産に特化し貿易することで、全体の利益が増えるという考え方。リカードの比較生産費説が有名。"},{"word":"国際収支","text":"一国と外国との経済取引の記録。経常収支（貿易やサービスの収支など）が中心的な項目になる。"},{"word":"為替相場","text":"円とドルなど、通貨同士の交換比率。変動相場制のもとでは市場の需給で変動し、輸出入や物価に影響を与える。"},{"word":"IMFと世界銀行","text":"戦後の国際通貨体制を支える機関。IMFは国際通貨の安定、世界銀行は発展途上国への融資を主な役割とする。"},{"word":"GATTからWTOへ","text":"自由貿易を進める枠組みは、GATT（関税と貿易に関する一般協定）から、1995年にWTO（世界貿易機関）へと発展した。","diagram":{"type":"timeline","title":"自由貿易の枠組みの発展","items":[{"label":"GATT","sub":"関税と貿易に関する一般協定"},{"label":"1995年 WTOの発足","sub":"世界貿易機関へと発展する"}]}},{"word":"グローバル化の課題","text":"経済の結びつきが深まる一方、国内産業への打撃や格差の拡大、環境問題などへの対応が課題となっている。"}]},"情報||情報デザインとメディア":{"points":[{"word":"情報デザイン","text":"情報を、受け手にとって分かりやすく使いやすい形に整理し、表現する工夫。目的と対象を意識することが出発点になる。"},{"word":"ユニバーサルデザイン","text":"年齢や障がいの有無などにかかわらず、できるだけ多くの人が利用できるように配慮した設計の考え方。"},{"word":"色の使い方と配色","text":"色には感情に訴える効果や、情報を区別する働きがある。色覚の多様性にも配慮し、色だけに頼らない表現が求められる。"},{"word":"文字と可読性","text":"文字の大きさ、書体、行間などの工夫によって読みやすさは大きく変わる。対象や媒体に合わせた選択が大切。"},{"word":"メディアの特性","text":"新聞・テレビ・Web・SNSなど、媒体ごとに伝わる速さ、情報量、双方向性が異なる。目的に合った媒体の選択が必要になる。"},{"word":"情報の流れの設計","text":"受け手が情報を得るまでの手順（導線）を考えること。Webページの構成や案内表示の設計などがその例。"}]},"情報||モデル化とシミュレーション":{"points":[{"word":"モデル化","text":"現実の対象から、目的に必要な要素だけを取り出して単純化すること。地図や天気予報の計算モデルもその例。","diagram":{"type":"flow","title":"モデル化から検証まで","items":[{"label":"モデル化","sub":"必要な要素だけを取り出して単純化する"},{"label":"シミュレーション","sub":"モデルを使って実験や予測を行う"},{"label":"結果の検証","sub":"実際のデータと比べて確かめる"}]}},{"word":"シミュレーション","text":"モデルを使って、コンピュータ上で実験や予測を行うこと。実際には試せない条件も安全に検証できる。"},{"word":"乱数と確率的なモデル","text":"サイコロのように結果が確率で決まる現象は、乱数を使ったシミュレーション（モンテカルロ法など）で近似できる。"},{"word":"モデルの仮定","text":"モデルは現実を単純化しているため、置いた仮定によって結果が変わる。仮定を意識して結果を読む必要がある。"},{"word":"シミュレーションの活用例","text":"天気予報、交通の渋滞予測、災害時の避難計画、製品の設計など、社会のさまざまな場面で使われている。"},{"word":"結果の検証","text":"シミュレーションの結果は、実際のデータと比較して確かめることで信頼性が高まる。予測と現実のずれの原因を考えることも大切。"}]}};
